/// What a context menu takes from the store about a location: what the
/// filesystem can do, whether it is writable and, for a sidebar place, the
/// item at the location. Probed off the UI thread and kept until the
/// location changes.
#[derive(Clone, Debug)]
struct LocationFacts {
    capabilities: musheen_core::CapabilityMatrix,
    writable: CapabilityState,
    /// The item at the location, once a sidebar menu asked for it.
    resolution: Option<LocationResolution>,
}

#[derive(Clone, Debug)]
struct LocationResolution {
    /// The sidebar menu the resolution was probed for; a later menu asks
    /// again, so a place whose target went away is seen as it is now.
    menu_generation: u64,
    item: Option<StoreItem>,
    /// What a link at the location leads to; `None` for a dangling link.
    link_target: Option<StoreItem>,
    /// The item is a link whose target is gone.
    dead_link: bool,
}

/// One question a menu or the toolbar could not answer from the caches.
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
enum StoreProbe {
    Executable { id: ItemId, path: StorePath },
    Location { location: StorePath, resolve: bool },
}

/// The store's answer to a probe, applied to the caches on the UI thread.
enum StoreProbeResult {
    Executable {
        id: ItemId,
        state: Option<CapabilityState>,
    },
    Location {
        location: StorePath,
        facts: Box<LocationFacts>,
    },
}

/// How to compose a menu again once its probes have answered.
#[derive(Clone)]
enum MenuRecompose {
    Request {
        tab_id: TabId,
        target: MenuTarget,
        location: StorePath,
        selection: Vec<CommandTargetRef>,
        resolved_item: Option<StoreItem>,
    },
    Sidebar {
        tab_id: TabId,
        target: MenuTarget,
        location: StorePath,
        identity: Option<ItemId>,
    },
}

impl MenuRecompose {
    fn target(&self) -> MenuTarget {
        match self {
            Self::Request { target, .. } | Self::Sidebar { target, .. } => *target,
        }
    }
}

/// A command target the store confirmed off the UI thread: the item at the
/// path and, for a link, what it leads to.
#[derive(Clone, Debug)]
struct ResolvedTarget {
    item: StoreItem,
    link_target: Option<StoreItem>,
}

impl ResolvedTarget {
    /// A directory, or a link that leads to one. Sidebar places such as
    /// $HOME/Desktop are often links, and they get the directory commands.
    fn opens_as_directory(&self) -> bool {
        match self.item.kind() {
            ItemKind::Directory => true,
            ItemKind::SymbolicLink => self
                .link_target
                .as_ref()
                .is_some_and(|target| target.kind() == ItemKind::Directory),
            ItemKind::RegularFile | ItemKind::Other => false,
        }
    }
}

/// The one directory a target-based command acts on: a single target that
/// opens as a directory.
fn single_directory_target(
    targets: &[CommandTargetRef],
    resolved: &[ResolvedTarget],
) -> Option<StorePath> {
    let ([target], [resolved]) = (targets, resolved) else {
        return None;
    };
    resolved.opens_as_directory().then(|| target.path().clone())
}

/// The probes a menu composition queued, and how to compose it again.
/// `deferring` says whether a probe decides the menu's commands, so the
/// popup waits for it; a probe that only adds a Send To destination lets
/// the popup open at once and rebuilds it later.
struct PendingMenuProbe {
    probes: Vec<StoreProbe>,
    recompose: MenuRecompose,
    deferring: bool,
}

