#[derive(Clone, Copy)]
enum IndexedContextSource {
    Pointer,
    Keyboard,
}

impl IndexedContextSource {
    fn focus_matches(self, requested: &ItemId, current: Option<&ItemId>) -> bool {
        matches!(self, Self::Pointer) || current == Some(requested)
    }
}

impl IndexedViewport {
    const MAX_RANGES: usize = 16;

    fn new(generation: u64, capacity: usize) -> Self {
        Self {
            generation,
            capacity: capacity.max(1),
            loaded: VecDeque::new(),
            pending: None,
        }
    }

    /// The rows to load for `requested`: padded on both sides for scrolling
    /// with what the capacity leaves, cut to `visible_count`, and never more
    /// than the capacity. The requested rows are always inside the load.
    fn load_range(
        &self,
        requested: &std::ops::Range<usize>,
        visible_count: usize,
    ) -> std::ops::Range<usize> {
        let padding = (self.capacity.saturating_sub(requested.len()) / 2).min(requested.len());
        let start = requested.start.saturating_sub(padding);
        let end = requested
            .end
            .saturating_add(padding)
            .min(visible_count)
            .min(start.saturating_add(self.capacity));
        start..end
    }

    #[cfg(test)]
    fn loaded_len(&self) -> usize {
        self.loaded.iter().map(|(_, items)| items.len()).sum()
    }

    fn covers(&self, range: &std::ops::Range<usize>) -> bool {
        self.loaded
            .iter()
            .any(|(loaded, _)| loaded.start <= range.start && loaded.end >= range.end)
    }

    fn matches_pending(&self, generation: u64, range: &std::ops::Range<usize>) -> bool {
        self.generation == generation && self.pending.as_ref() == Some(range)
    }

    fn item(&self, position: usize) -> Option<StoreItem> {
        self.row(position).map(|(item, _)| item)
    }

    fn row(&self, position: usize) -> Option<(StoreItem, u64)> {
        self.loaded
            .iter()
            .rev()
            .find_map(|(range, items)| items.get(position.checked_sub(range.start)?).cloned())
    }

    fn insert(&mut self, range: std::ops::Range<usize>, items: Vec<(StoreItem, u64)>) {
        self.loaded.push_back((range, items));
        while self.loaded.len() > Self::MAX_RANGES
            || self
                .loaded
                .iter()
                .map(|(_, items)| items.len())
                .sum::<usize>()
                > self.capacity
        {
            self.loaded.pop_front();
        }
    }
}

