fn normalized_pointer_bounds(start: Point<Pixels>, end: Point<Pixels>) -> Bounds<Pixels> {
    let left = start.x.as_f32().min(end.x.as_f32());
    let top = start.y.as_f32().min(end.y.as_f32());
    let right = start.x.as_f32().max(end.x.as_f32());
    let bottom = start.y.as_f32().max(end.y.as_f32());
    Bounds::from_corners(point(px(left), px(top)), point(px(right), px(bottom)))
}

fn is_rubber_band_start(
    position: Point<Pixels>,
    surface: Bounds<Pixels>,
    chrome_height: f32,
    scrollbar_width: f32,
) -> bool {
    let left = surface.left().as_f32();
    let right = (surface.right().as_f32() - scrollbar_width.max(0.0)).max(left);
    let top = (surface.top().as_f32() + chrome_height.max(0.0)).min(surface.bottom().as_f32());
    let x = position.x.as_f32();
    let y = position.y.as_f32();
    x >= left && x < right && y >= top && y <= surface.bottom().as_f32()
}

/// Height of one grid row as `rubber_band_indices` lays it out.
const RUBBER_BAND_GRID_ROW_HEIGHT: f32 = 116.0;

/// Splits a vertical scroll distance into the first visible row and the
/// offset of that row's top from the viewport top, which is zero or negative.
/// The message to show when a page or index step failed: the index error
/// when the folder keeps its rows, otherwise the folder's error state.
fn directory_failure_message(directory: &DirectoryModel) -> Option<Box<str>> {
    directory
        .index_error()
        .map(Box::from)
        .or_else(|| match directory.state() {
            DirectoryState::Error(message) => Some(message.clone()),
            _ => None,
        })
}

fn rubber_band_scroll_position(scrolled: Pixels, row_pitch: Pixels) -> (usize, Pixels) {
    if row_pitch <= px(0.) || scrolled <= px(0.) {
        return (0, px(0.));
    }
    let row = (scrolled.as_f32() / row_pitch.as_f32()).floor();
    (row as usize, -(scrolled - row_pitch * row))
}

fn rubber_band_indices(selection: Bounds<Pixels>, surface: RubberBandSurface) -> Vec<usize> {
    let RubberBandSurface {
        bounds,
        layout,
        item_count,
        columns,
        top_inset,
        first_item_index,
        first_item_offset,
        list_row_height,
    } = surface;
    if item_count == 0 {
        return Vec::new();
    }
    let content_left = bounds.left().as_f32() + 16.0;
    let content_top = bounds.top().as_f32() + top_inset + first_item_offset;
    let selection_top = selection.top().as_f32();
    let selection_bottom = selection.bottom().as_f32();
    let first_row;
    let last_row;
    let row_height;
    match layout {
        Layout::Details | Layout::List | Layout::Columns => {
            row_height = list_row_height.max(1.0);
            first_row = ((selection_top - content_top) / row_height)
                .floor()
                .max(0.0) as usize;
            last_row = ((selection_bottom - content_top) / row_height)
                .floor()
                .max(0.0) as usize;
            return (first_row..=last_row)
                .filter_map(|visible_index| {
                    let index = first_item_index.saturating_add(visible_index);
                    if index >= item_count {
                        return None;
                    }
                    let item = Bounds::new(
                        point(
                            px(content_left),
                            px(content_top + visible_index as f32 * row_height),
                        ),
                        size(
                            px((bounds.size.width.as_f32() - 32.0).max(0.0)),
                            px((row_height - 2.0).max(1.0)),
                        ),
                    );
                    selection.intersects(&item).then_some(index)
                })
                .collect();
        }
        Layout::Cards | Layout::Grid | Layout::Adaptive => {
            row_height = RUBBER_BAND_GRID_ROW_HEIGHT;
            first_row = ((selection_top - content_top) / row_height)
                .floor()
                .max(0.0) as usize;
            last_row = ((selection_bottom - content_top) / row_height)
                .floor()
                .max(0.0) as usize;
        }
    }
    let columns = columns.max(1);
    let item_width = if layout == Layout::Cards {
        240.0
    } else {
        128.0
    };
    let gap = 8.0;
    (first_row..=last_row)
        .flat_map(|visible_row| {
            (0..columns).filter_map(move |column| {
                let visible_index = visible_row * columns + column;
                let index = first_item_index.saturating_add(visible_index);
                (index < item_count).then_some((index, visible_row, column))
            })
        })
        .filter_map(|(index, visible_row, column)| {
            let item = Bounds::new(
                point(
                    px(content_left + column as f32 * (item_width + gap)),
                    px(content_top + visible_row as f32 * row_height),
                ),
                size(px(item_width), px(108.0)),
            );
            selection.intersects(&item).then_some(index)
        })
        .collect()
}

