struct VolumeUnlockDialog {
    volume_label: Box<str>,
    /// The third-party input owns the sole plaintext copy while editing. A
    /// native window close drops this entity; submit moves a temporary copy
    /// into `SecretBuffer` and immediately clears the input.
    secret: Entity<InputState>,
    focus: FocusHandle,
    pending_focus: bool,
    empty: bool,
    submitted_secret: Option<SecretBuffer>,
    catalog: Catalog,
}

impl EventEmitter<VolumeUnlockEvent> for VolumeUnlockDialog {}

impl VolumeUnlockDialog {
    fn new(
        volume_label: impl Into<Box<str>>,
        catalog: Catalog,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Self {
        let placeholder = catalog
            .message("volume-unlock-passphrase")
            .expect("the unlock passphrase prompt is localized")
            .to_owned();
        Self {
            volume_label: volume_label.into(),
            secret: cx.new(|cx| {
                InputState::new(window, cx)
                    .placeholder(placeholder)
                    .masked(true)
            }),
            focus: cx.focus_handle(),
            pending_focus: true,
            empty: false,
            submitted_secret: None,
            catalog,
        }
    }

    fn submit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let secret = self.secret.read(cx).value().to_string();
        if secret.is_empty() {
            self.empty = true;
            cx.notify();
            return;
        }
        self.submitted_secret = Some(SecretBuffer::new(secret.into_bytes()));
        self.secret
            .update(cx, |secret, cx| secret.set_value("", window, cx));
        cx.emit(VolumeUnlockEvent::Submitted);
        window.defer(cx, |window, _| window.remove_window());
    }
}

impl Render for VolumeUnlockDialog {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if self.pending_focus {
            self.secret
                .update(cx, |secret, cx| secret.focus(window, cx));
            self.pending_focus = false;
        }
        let title = self
            .catalog
            .message("volume-unlock-title")
            .expect("the unlock title is localized")
            .to_owned();
        div()
            .id("volume-unlock-dialog")
            .test_support()
            .key_context("VolumeUnlockDialog")
            .role(Role::Dialog)
            .aria_label(title.clone())
            .track_focus(&self.focus)
            .flex()
            .flex_col()
            .gap_3()
            .p_4()
            .on_action(cx.listener(|this, _: &Escape, window, cx| {
                this.secret
                    .update(cx, |secret, cx| secret.set_value("", window, cx));
                cx.emit(VolumeUnlockEvent::Cancelled);
                window.defer(cx, |window, _| window.remove_window());
            }))
            .child(div().text_lg().child(title))
            .child(format!(
                "{}: {}",
                self.catalog
                    .message("volume-unlock-volume")
                    .expect("the unlock volume label is localized"),
                self.volume_label
            ))
            .child(
                Input::new(&self.secret)
                    .id("volume-unlock-passphrase")
                    .content_type(InputContentType::Password)
                    .mask_toggle(),
            )
            .when(self.empty, |dialog| {
                dialog.child(
                    div()
                        .id("volume-unlock-error")
                        .test_support()
                        .role(Role::Alert)
                        .child(
                            self.catalog
                                .message("volume-unlock-empty")
                                .expect("the empty-passphrase error is localized")
                                .to_owned(),
                        ),
                )
            })
            .child(
                Button::new("volume-unlock-submit")
                    .label(
                        self.catalog
                            .message("command-unlock")
                            .expect("the unlock command is localized"),
                    )
                    .on_click(cx.listener(|this, _, window, cx| this.submit(window, cx))),
            )
            .child(
                Button::new("volume-unlock-cancel")
                    .label(
                        self.catalog
                            .message("dialog.cancel")
                            .expect("the cancel action is localized"),
                    )
                    .on_click(cx.listener(|this, _, window, cx| {
                        this.secret
                            .update(cx, |secret, cx| secret.set_value("", window, cx));
                        cx.emit(VolumeUnlockEvent::Cancelled);
                        window.defer(cx, |window, _| window.remove_window());
                    })),
            )
    }
}

/// The menu layer asks this adapter for a provider-backed destination result;
/// it deliberately delegates the decision to the operation queue instead of
/// accepting a UI-provided writable flag.
struct ContextTransferDestinationResolver<'a> {
    operation_hub: &'a OperationHub,
    payload: &'a FileDragPayload,
    catalog: &'a Catalog,
}

impl ContextMenuDestinationResolver for ContextTransferDestinationResolver<'_> {
    fn resolve_context_menu_destination(
        &self,
        destination: &StorePath,
    ) -> musheen_core::ResolvedDestination {
        if self
            .operation_hub
            .can_accept_drop(self.payload, destination)
        {
            musheen_core::ResolvedDestination::writable(destination.clone())
        } else {
            musheen_core::ResolvedDestination::read_only(
                destination.clone(),
                self.catalog
                    .message("context.destination-refused")
                    .expect("destination refusal is localized"),
            )
        }
    }
}

/// The directory that holds every tab's index. `run` resolves it from the
/// environment; tests point it at a temporary directory. `None` means no
/// cache directory is available.
#[derive(Clone, Debug)]
pub(crate) struct DirectoryIndexRoot(pub(crate) Option<PathBuf>);

impl Global for DirectoryIndexRoot {}

pub fn run(initial_path: PathBuf) {
    gpui_kit::application()
        .with_assets(MusheenAssets)
        .run(move |cx| {
            gpui_kit::init(cx);
            cx.set_global(DirectoryIndexRoot(crate::directory::directory_index_root()));
            install_navigation_key_bindings(cx);
            install_native_theme(cx);
            install_file_manager1(cx);
            let settings = musheen_desktop::SettingsStore::for_current_user()
                .load()
                .unwrap_or_else(|error| {
                    eprintln!("Musheen could not load settings: {error}");
                    musheen_desktop::SettingsDocument::default()
                });
            install_desktop_portals(&settings, cx);
            let maintenance_readiness = install_desktop_maintenance(&settings, cx);
            if std::env::var_os("MUSHEEN_THEME_PREVIEW").is_none() {
                crate::settings::apply_appearance(&settings, cx);
            }
            let limits = settings
                .resource_limits_snapshot()
                .expect("loaded settings limits are validated");
            cx.set_global(crate::settings::RuntimeSettings(settings.clone()));
            cx.set_global(crate::settings::RemoteConnectionsRevision(0));
            let width = preview_window_width(
                std::env::var("MUSHEEN_PREVIEW_WINDOW_WIDTH")
                    .ok()
                    .as_deref(),
            );
            let height = preview_window_height(
                std::env::var("MUSHEEN_PREVIEW_WINDOW_HEIGHT")
                    .ok()
                    .as_deref(),
            );
            let fallback = StorePath::from_unix_path(initial_path.into_os_string());
            let store = SessionStore::for_current_user();
            let providers = ProviderRuntime::from_settings(&settings).unwrap_or_else(|error| {
                eprintln!("Musheen could not load remote connections: {error}");
                ProviderRuntime::for_current_user()
            });
            let application = (settings.value("general.restore_session").as_deref()
                != Some("false")
                && settings.value("general.startup").as_deref() == Some("last-session"))
            .then(|| {
                restore_application_session(&store, fallback.clone(), |location| {
                    providers.location_exists(location)
                })
            })
            .flatten()
            .unwrap_or_else(|| {
                ApplicationSession::new(vec![WindowSession::new(fallback)])
                    .expect("a single fallback window is a valid application session")
            });
            let coordinator = Arc::new(Mutex::new(SessionCoordinator::new(store, application)));
            let operation_hub =
                OperationHub::for_current_user_with_provider_runtime(&limits, &providers);
            install_desktop_notifications(&settings, operation_hub.clone(), cx);
            let volume_runtime = VolumeRuntime::system_with_usage(Arc::new(HubVolumeUsage {
                hub: operation_hub.clone(),
            }))
            .expect("the system volume runtime has no fallible construction");
            let catalog_store = CatalogStore::for_current_user();
            let catalog_document = catalog_store
                .update(|catalog| {
                    catalog.recents_mut().set_recording_enabled(
                        settings.value("general.record_history").as_deref() != Some("false"),
                    );
                    Ok(catalog.clone())
                })
                .unwrap_or_else(|error| {
                    eprintln!("Musheen could not load or update its catalog: {error}");
                    CatalogDocument::default()
                });
            let catalog_binding = CatalogBinding::persistent_with_xattr_opt_in(
                catalog_store,
                catalog_document,
                settings.value("general.store_tags_in_files").as_deref() == Some("true"),
            );
            let windows = coordinator
                .lock()
                .expect("session coordinator lock is not poisoned")
                .entries()
                .into_iter()
                .map(|(window_id, navigation)| {
                    (
                        application_window_options(width, height, cx),
                        navigation,
                        SessionBinding {
                            coordinator: Arc::clone(&coordinator),
                            window_id,
                            operation_hub: operation_hub.clone(),
                            volume_runtime: Some(volume_runtime.clone()),
                            catalog: catalog_binding.clone(),
                            providers: providers.clone(),
                        },
                    )
                })
                .collect::<Vec<_>>();
            cx.spawn(async move |cx| {
                for (window_options, navigation, binding) in windows {
                    let limits = limits.clone();
                    let window_readiness = maintenance_readiness.clone();
                    let initial_location = navigation.focused_tab().location().clone();
                    cx.open_window(window_options, move |window, cx| {
                        let view = cx.new(|cx| {
                            MusheenApp::new_with_navigation(
                                navigation,
                                Some(binding),
                                None,
                                limits.clone(),
                                true,
                                cx,
                            )
                        });
                        view.update(cx, |state, cx| {
                            state.start_initial_load(initial_location, cx);
                        });
                        register_file_manager_window(&view, window, cx);
                        window.on_next_frame(move |_, _| {
                            window_readiness.mark_first_window_ready();
                        });
                        cx.new(|cx| Root::new(view, window, cx))
                    })
                    .expect("Musheen could not restore a browsing window");
                }
            })
            .detach();
        });
}

struct DesktopPortalClient {
    client: Arc<musheen_desktop::PortalClient<musheen_desktop::AshpdPortalTransport>>,
    sandboxed: bool,
}

impl Global for DesktopPortalClient {}

fn install_desktop_portals(settings: &musheen_desktop::SettingsDocument, cx: &mut App) {
    let sandbox = musheen_desktop::SandboxState::detect();
    let backend_enabled = settings.value("integrations.portal").as_deref() == Some("musheen");
    let own_backend = backend_enabled.then(|| musheen_desktop::MUSHEEN_PORTAL_BACKEND.into());
    cx.set_global(DesktopPortalClient {
        client: Arc::new(musheen_desktop::PortalClient::new(
            musheen_desktop::AshpdPortalTransport::default(),
            sandbox,
            own_backend,
        )),
        sandboxed: sandbox == musheen_desktop::SandboxState::Sandboxed,
    });
    #[cfg(feature = "portal-backend")]
    if backend_enabled {
        install_portal_backend(cx);
    }
    #[cfg(not(feature = "portal-backend"))]
    if backend_enabled {
        eprintln!("Musheen's portal backend is enabled in settings but was not built");
    }
}

#[cfg(feature = "portal-backend")]
struct PortalChooserEnvelope {
    request: musheen_desktop::BackendChooserRequest,
    response: async_channel::Sender<musheen_desktop::BackendChooserDecision>,
}

#[cfg(feature = "portal-backend")]
struct GpuiPortalChooser {
    requests: async_channel::Sender<PortalChooserEnvelope>,
}

#[cfg(feature = "portal-backend")]
impl musheen_desktop::BackendChooserUi for GpuiPortalChooser {
    fn choose(
        &self,
        request: musheen_desktop::BackendChooserRequest,
        cancellation: CancellationToken,
    ) -> musheen_core::BoxFuture<
        'static,
        Result<musheen_desktop::BackendChooserDecision, musheen_desktop::PortalError>,
    > {
        let requests = self.requests.clone();
        Box::pin(async move {
            let (response, decision) = async_channel::bounded(1);
            requests
                .try_send(PortalChooserEnvelope { request, response })
                .map_err(|error| {
                    musheen_desktop::PortalError::Unavailable(error.to_string().into())
                })?;
            futures_lite::future::race(
                async {
                    decision.recv().await.map_err(|error| {
                        musheen_desktop::PortalError::Unavailable(error.to_string().into())
                    })
                },
                async {
                    futures_lite::future::poll_fn(|context| {
                        if cancellation.is_cancelled() {
                            std::task::Poll::Ready(())
                        } else {
                            cancellation.register_waker(context.waker());
                            if cancellation.is_cancelled() {
                                std::task::Poll::Ready(())
                            } else {
                                std::task::Poll::Pending
                            }
                        }
                    })
                    .await;
                    Err(musheen_desktop::PortalError::Cancelled)
                },
            )
            .await
        })
    }
}

#[cfg(feature = "portal-backend")]
fn install_portal_backend(cx: &mut App) {
    let (requests, receiver) = async_channel::bounded(16);
    cx.spawn(async move |cx| {
        while let Ok(envelope) = receiver.recv().await {
            cx.update(|cx| route_portal_chooser(envelope, cx));
        }
    })
    .detach();
    let retry_executor = cx.background_executor().clone();
    cx.background_executor()
        .spawn(async move {
            let mut retry_delay = Duration::from_secs(1);
            loop {
                match musheen_desktop::serve_file_chooser_backend(
                    None,
                    Arc::new(GpuiPortalChooser {
                        requests: requests.clone(),
                    }),
                    musheen_desktop::MUSHEEN_PORTAL_BACKEND,
                    ApplicationIdentity::ID,
                )
                .await
                {
                    Ok(connection) => {
                        retry_delay = Duration::from_secs(1);
                        connection.closed().await;
                    }
                    Err(error) => {
                        eprintln!("Musheen could not export its portal backend: {error}");
                    }
                }
                retry_executor.timer(retry_delay).await;
                retry_delay = (retry_delay * 2).min(Duration::from_secs(30));
            }
        })
        .detach();
}

#[cfg(feature = "portal-backend")]
fn route_portal_chooser(envelope: PortalChooserEnvelope, cx: &mut App) {
    let target = cx
        .global::<FileManagerWindows>()
        .entries
        .iter()
        .rev()
        .find_map(|entry| entry.view.upgrade());
    let Some(view) = target else {
        let _ = envelope
            .response
            .try_send(musheen_desktop::BackendChooserDecision::Cancelled);
        return;
    };
    view.update(cx, |state, cx| state.open_portal_chooser(envelope, cx));
}

fn install_file_manager1(cx: &mut App) {
    if cx.has_global::<FileManagerWindows>() {
        return;
    }
    cx.set_global(FileManagerWindows::default());
    let (sender, receiver) = async_channel::bounded(32);
    spawn_file_manager1_service(
        musheen_desktop::MUSHEEN_FILE_MANAGER_NAME,
        sender.clone(),
        cx,
    );
    spawn_file_manager1_service(musheen_desktop::FILE_MANAGER_NAME, sender, cx);
    cx.spawn(async move |cx| {
        while let Ok(envelope) = receiver.recv().await {
            cx.update(|cx| {
                route_file_manager_request(envelope, cx);
            });
        }
    })
    .detach();
}

fn spawn_file_manager1_service(
    name: &'static str,
    sender: async_channel::Sender<musheen_desktop::FileManagerRequestEnvelope>,
    cx: &mut App,
) {
    let retry_executor = cx.background_executor().clone();
    cx.background_executor()
        .spawn(async move {
            let mut retry_delay = Duration::from_secs(1);
            loop {
                match musheen_desktop::serve_file_manager1_named(
                    None,
                    name,
                    Arc::new(sender.clone()),
                )
                .await
                {
                    Ok(connection) => {
                        retry_delay = Duration::from_secs(1);
                        connection.closed().await;
                    }
                    Err(error) => {
                        eprintln!("Musheen could not export {name}: {error}");
                    }
                }
                retry_executor.timer(retry_delay).await;
                retry_delay = (retry_delay * 2).min(Duration::from_secs(30));
            }
        })
        .detach();
}

fn register_file_manager_window(view: &Entity<MusheenApp>, window: &mut Window, cx: &mut App) {
    let window_id = window.window_handle().window_id();
    let release_binding = view.read(cx).session_binding.clone();
    let release = cx.observe_release(view, move |_, cx| {
        retire_file_manager_window(window_id, release_binding.as_ref(), cx);
    });
    let close_binding = view.read(cx).session_binding.clone();
    let close = cx.on_window_closed(move |cx, closed| {
        if closed == window_id {
            retire_file_manager_window(window_id, close_binding.as_ref(), cx);
        }
    });
    let windows = cx.global_mut::<FileManagerWindows>();
    windows
        .entries
        .retain(|entry| entry.view.upgrade().is_some() && entry.window_id != window_id);
    windows.entries.push(RegisteredBrowserWindow {
        view: view.downgrade(),
        handle: window.window_handle(),
        window_id,
        _release: release,
        _close: close,
    });
}

fn retire_file_manager_window(window_id: WindowId, binding: Option<&SessionBinding>, cx: &mut App) {
    if cx.has_global::<FileManagerWindows>() {
        cx.global_mut::<FileManagerWindows>()
            .entries
            .retain(|entry| entry.window_id != window_id);
    }
    if let Some(binding) = binding {
        match binding.prepare_remove_window() {
            Ok(Some(prepared)) => {
                cx.background_executor()
                    .spawn(async move {
                        if let Err(error) = prepared.save_if_current() {
                            eprintln!("Musheen could not save its browsing session: {error}");
                        }
                    })
                    .detach();
            }
            Ok(None) => {}
            Err(error) => eprintln!("Musheen could not update its browsing session: {error}"),
        }
    }
}

fn route_file_manager_request(envelope: musheen_desktop::FileManagerRequestEnvelope, cx: &mut App) {
    let (request, acknowledgement) = envelope.into_parts();
    let target = cx
        .global::<FileManagerWindows>()
        .entries
        .iter()
        .rev()
        .find_map(|entry| entry.view.upgrade().map(|view| (view, entry.handle)));
    let Some((view, handle)) = target else {
        acknowledgement.complete(Err(musheen_desktop::FileManagerError::Unavailable));
        return;
    };
    if handle
        .update(cx, |_, window, _| window.activate_window())
        .is_err()
    {
        acknowledgement.complete(Err(musheen_desktop::FileManagerError::Unavailable));
        return;
    }
    let result = view.update(cx, |state, cx| {
        if state.browser_input_blocked() {
            state.activate_context_dialog(cx);
            return Err(musheen_desktop::FileManagerError::Blocked);
        }
        state.apply_file_manager_request(request, acknowledgement.clone(), cx)
    });
    if let Err(error) = result {
        acknowledgement.complete(Err(error));
    }
}

fn install_desktop_maintenance(
    settings: &musheen_desktop::SettingsDocument,
    cx: &mut App,
) -> musheen_desktop::WindowReadiness {
    let readiness = musheen_desktop::WindowReadiness::new();
    let (offers, receiver) = async_channel::bounded(1);
    let mut tasks: Vec<Arc<dyn musheen_desktop::MaintenanceTask>> = vec![Arc::new(
        musheen_desktop::LogRotationTask::for_current_user(3),
    )];
    if settings.value("advanced.updates").as_deref() == Some("true") {
        tasks.push(Arc::new(musheen_desktop::UpdateMaintenanceTask::new(
            musheen_desktop::UpdateCheck::new(
                musheen_desktop::HttpsMetadataFetcher::default(),
                musheen_desktop::UpdateMetadataVerifier::project_key(),
                env!("CARGO_PKG_VERSION"),
            ),
            musheen_desktop::UpdatePolicy::enabled("https://updates.musheen.app/v1/latest.json", 0),
            offers,
        )));
    }
    let worker = musheen_desktop::MaintenanceCoordinator::new(readiness.clone(), tasks).start();
    let failures = worker.failures();
    cx.set_global(DesktopMaintenanceOwner { _worker: worker });
    cx.spawn(async move |cx| {
        while failures.recv().await.is_ok() {
            cx.update(|cx| {
                let target = cx
                    .global::<FileManagerWindows>()
                    .entries
                    .iter()
                    .rev()
                    .find_map(|entry| entry.view.upgrade());
                if let Some(view) = target {
                    view.update(cx, |state, cx| {
                        state.operation_error = Some(
                            state
                                .catalog
                                .message("maintenance-task-failed")
                                .expect("maintenance failure is localized")
                                .into(),
                        );
                        cx.notify();
                    });
                }
            });
        }
    })
    .detach();
    cx.spawn(async move |cx| {
        while let Ok(offer) = receiver.recv().await {
            cx.update(|cx| {
                let target = cx
                    .global::<FileManagerWindows>()
                    .entries
                    .iter()
                    .rev()
                    .find_map(|entry| entry.view.upgrade());
                if let Some(view) = target {
                    view.update(cx, |state, cx| {
                        state.update_offer = Some(offer);
                        state.application_notice = Some("update-available");
                        cx.notify();
                    });
                }
            });
        }
    })
    .detach();
    readiness
}

fn install_desktop_notifications(
    settings: &musheen_desktop::SettingsDocument,
    operation_hub: OperationHub,
    cx: &mut App,
) {
    let enabled = settings.value("integrations.notifications").as_deref() != Some("false");
    let (actions, action_receiver) = async_channel::bounded(32);
    cx.set_global(DesktopNotificationOwner::new(
        enabled,
        Arc::new(musheen_desktop::NotifyRustSink),
        actions,
    ));
    cx.spawn(async move |cx| {
        while let Ok(action) = action_receiver.recv().await {
            cx.update(|cx| activate_notification_action(action, cx));
        }
    })
    .detach();
    let catalog = Catalog::system().expect("the installed locale catalogs are valid");
    let completed_summary = catalog
        .message("notification-operation-completed")
        .expect("operation completion notification is localized")
        .to_owned();
    let failed_summary = catalog
        .message("notification-operation-failed")
        .expect("operation failure notification is localized")
        .to_owned();
    let action_label = catalog
        .message("notification-show-in-musheen")
        .expect("notification action label is localized")
        .to_owned();
    cx.spawn(async move |cx| {
        let mut revision = operation_hub.status_revision();
        loop {
            cx.background_executor()
                .timer(OPERATION_STATUS_REFRESH_INTERVAL)
                .await;
            let next = operation_hub.status_revision();
            if next == revision {
                continue;
            }
            revision = next;
            let entries = operation_hub
                .status()
                .lock()
                .map(|status| status.visible_entries().into_iter().cloned().collect::<Vec<_>>())
                .unwrap_or_default();
            cx.update(|cx| {
                let visible = any_browser_window_visible(cx);
                for entry in entries {
                    let outcome = match entry.status() {
                        OperationStatus::Completed => {
                            musheen_desktop::NotificationOutcome::Completed
                        }
                        OperationStatus::Failed
                        | OperationStatus::Recoverable
                        | OperationStatus::NeedsAttention
                        | OperationStatus::PartialSuccess => {
                            musheen_desktop::NotificationOutcome::Failed
                        }
                        _ => continue,
                    };
                    let marker = NotificationMarker {
                        job: entry.id(),
                        generation: entry.generation(),
                    };
                    if visible {
                        cx.global_mut::<DesktopNotificationOwner>().suppress(marker);
                        continue;
                    }
                    if !cx.global_mut::<DesktopNotificationOwner>().claim(marker) {
                        continue;
                    }
                    let command = operation_command_id(entry.kind());
                    let summary: Box<str> = match outcome {
                        musheen_desktop::NotificationOutcome::Completed => &completed_summary,
                        musheen_desktop::NotificationOutcome::Failed => &failed_summary,
                        musheen_desktop::NotificationOutcome::Progress => unreachable!(),
                    }
                    .as_str()
                    .into();
                    let action_label = action_label.clone();
                    cx.spawn(async move |cx| {
                        cx.background_executor().timer(Duration::from_secs(2)).await;
                        cx.update(|cx| {
                            let delivery = cx
                                .global_mut::<DesktopNotificationOwner>()
                                .finish(marker);
                            if any_browser_window_visible(cx) {
                                return;
                            }
                            let Some((sink, actions)) = delivery else {
                                return;
                            };
                            let event = match outcome {
                                musheen_desktop::NotificationOutcome::Completed => {
                                    musheen_desktop::NotificationEvent::completed(
                                        marker.job,
                                        command,
                                        summary,
                                    )
                                }
                                musheen_desktop::NotificationOutcome::Failed => {
                                    musheen_desktop::NotificationEvent::failed(
                                        marker.job,
                                        command,
                                        summary,
                                    )
                                }
                                musheen_desktop::NotificationOutcome::Progress => unreachable!(),
                            };
                            cx.background_executor()
                                .spawn(async move {
                                    let policy = musheen_desktop::NotificationPolicy::new(sink);
                                    if let Err(error) = policy.publish(
                                        event,
                                        musheen_desktop::OperationVisibility::NoVisibleWindow,
                                        &action_label,
                                        actions,
                                    ) {
                                        eprintln!(
                                            "Musheen could not send an operation notification: {error}"
                                        );
                                    }
                                })
                                .detach();
                        });
                    })
                    .detach();
                }
            });
        }
    })
    .detach();
}

fn any_browser_window_visible(cx: &mut App) -> bool {
    let handles = cx
        .global::<FileManagerWindows>()
        .entries
        .iter()
        .filter(|entry| entry.view.upgrade().is_some())
        .map(|entry| entry.handle)
        .collect::<Vec<_>>();
    handles.into_iter().any(|handle| {
        handle
            .update(cx, |_, window, _| window.is_visible())
            .unwrap_or(false)
    })
}

fn activate_notification_action(action: musheen_desktop::NotificationAction, cx: &mut App) {
    let target = cx
        .global::<FileManagerWindows>()
        .entries
        .iter()
        .rev()
        .find_map(|entry| entry.view.upgrade().map(|view| (view, entry.handle)));
    let Some((view, handle)) = target else {
        return;
    };
    let _ = handle.update(cx, |_, window, _| window.activate_window());
    view.update(cx, |state, cx| {
        if state
            .operation_hub
            .status()
            .lock()
            .is_ok_and(|status| status.entry(action.job_id()).is_some())
        {
            state.status_center_open = true;
            state.refresh_undo_availability(cx);
            cx.notify();
        }
    });
}

fn operation_command_id(kind: OperationKind) -> CommandId {
    let id = match kind {
        OperationKind::Copy => "clipboard.copy",
        OperationKind::Move => "clipboard.move_to",
        OperationKind::Trash => "file.move_to_trash",
        OperationKind::PermanentDelete => "file.delete_permanently",
        OperationKind::CreateFile => "create.empty_file",
        OperationKind::CreateDirectory => "create.directory",
        OperationKind::Rename => "file.rename",
        OperationKind::SymbolicLink => "file.create_symbolic_link",
        OperationKind::HardLink => "file.create_hard_link",
        OperationKind::SetPermissions
        | OperationKind::SetOwnership
        | OperationKind::SetExtendedAttribute => "item.permissions",
        OperationKind::Compress => "file.compress",
        OperationKind::Extract => "archive.extract",
        OperationKind::Restore => "trash.restore",
        OperationKind::Hash => "item.properties",
        OperationKind::Preview => "file.preview",
    };
    CommandId::new(id).expect("built-in operation command IDs are valid")
}

fn application_window_options(width: f32, height: f32, cx: &App) -> WindowOptions {
    WindowOptions {
        window_bounds: Some(WindowBounds::centered(size(px(width), px(height)), cx)),
        titlebar: Some(TitlebarOptions {
            title: Some("Musheen".into()),
            ..TitlebarOptions::default()
        }),
        app_id: Some(ApplicationIdentity::ID.into()),
        window_min_size: Some(size(px(720.), px(480.))),
        ..WindowOptions::default()
    }
}

fn detached_window_options() -> WindowOptions {
    WindowOptions {
        titlebar: Some(TitlebarOptions {
            title: Some("Musheen".into()),
            ..TitlebarOptions::default()
        }),
        app_id: Some(ApplicationIdentity::ID.into()),
        window_min_size: Some(size(px(720.), px(480.))),
        ..WindowOptions::default()
    }
}

fn install_native_theme(cx: &mut App) {
    if let Ok(requested) = std::env::var("MUSHEEN_THEME_PREVIEW")
        && let Some((is_dark, high_contrast)) = preview_theme(&requested)
    {
        let mut preferences = native_theme::AccessibilityPreferences::from_system();
        preferences.high_contrast = high_contrast;
        preferences.reduce_transparency |= high_contrast;
        if let Ok((theme, resolved)) =
            native_theme_gpui::from_preset("adwaita", is_dark, &preferences)
        {
            native_theme_gpui::apply(theme, &resolved, &preferences, cx);
            return;
        }
    }

    match SystemTheme::from_system() {
        Ok(system_theme) => native_theme_gpui::apply_system_theme(&system_theme, cx),
        Err(error) => {
            eprintln!("Musheen could not read the system theme: {error}. Using Adwaita.");
            let preferences = native_theme::AccessibilityPreferences::from_system();
            install_fallback_theme(
                prefers_dark_appearance(cx.window_appearance()),
                &preferences,
                cx,
            );
        }
    }
    crate::theme::runtime::install(cx);
}

/// Resolves every target at the store and refuses one that is gone or was
/// replaced. Runs on a background thread.
fn resolve_targets(
    store: &dyn Store,
    targets: &[CommandTargetRef],
    verification: &str,
    changed: &str,
) -> Result<Vec<ResolvedTarget>, Box<str>> {
    let mut resolved = Vec::with_capacity(targets.len());
    for target in targets {
        let current = store
            .resolve_item(target.path())
            .map_err(|error| Box::<str>::from(format!("{verification}: {error}")))?;
        match current {
            Some(item) if item.id() == target.id() && item.path() == target.path() => {
                let link_target = (item.kind() == ItemKind::SymbolicLink)
                    .then(|| store.resolve_link_target(item.path()).ok().flatten())
                    .flatten();
                resolved.push(ResolvedTarget { item, link_target });
            }
            _ => return Err(Box::<str>::from(changed)),
        }
    }
    Ok(resolved)
}

/// Asks the store one of a menu's questions. Runs on a background thread.
fn run_store_probe(
    store: &dyn Store,
    probe: StoreProbe,
    writable_failure_prefix: &str,
) -> StoreProbeResult {
    match probe {
        StoreProbe::Executable { id, path } => StoreProbeResult::Executable {
            id,
            state: store.executable_state(&path).ok(),
        },
        StoreProbe::Location { location, resolve } => {
            let capabilities = store.capabilities(&location);
            let writable = store.location_writable(&location).unwrap_or_else(|error| {
                CapabilityState::Unknown(
                    CapabilityReason::new(format!("{writable_failure_prefix}: {error}"))
                        .expect("the writable-location failure is visible"),
                )
            });
            let resolution = resolve.then(|| {
                let item = store.resolve_item(&location).ok().flatten();
                let is_link = item
                    .as_ref()
                    .is_some_and(|item| item.kind() == ItemKind::SymbolicLink);
                let link_target = item
                    .as_ref()
                    .filter(|_| is_link)
                    .and_then(|item| store.resolve_link_target(item.path()).ok().flatten());
                LocationResolution {
                    menu_generation: 0,
                    item,
                    dead_link: is_link && link_target.is_none(),
                    link_target,
                }
            });
            StoreProbeResult::Location {
                location,
                facts: Box::new(LocationFacts {
                    capabilities,
                    writable,
                    resolution,
                }),
            }
        }
    }
}

/// Installs both Adwaita presets when the system theme cannot be read. The
/// bridge keeps the variant applied last as the current mode, so the
/// variant the window prefers goes last.
/// Whether a window appearance asks for the dark fallback theme.
fn prefers_dark_appearance(appearance: gpui_kit::WindowAppearance) -> bool {
    matches!(
        appearance,
        gpui_kit::WindowAppearance::Dark | gpui_kit::WindowAppearance::VibrantDark
    )
}

fn install_fallback_theme(
    prefers_dark: bool,
    preferences: &native_theme::AccessibilityPreferences,
    cx: &mut App,
) {
    for is_dark in [!prefers_dark, prefers_dark] {
        if let Ok((theme, resolved)) =
            native_theme_gpui::from_preset("adwaita", is_dark, preferences)
        {
            native_theme_gpui::apply(theme, &resolved, preferences, cx);
        }
    }
}

fn preview_theme(value: &str) -> Option<(bool, bool)> {
    match value {
        "light" => Some((false, false)),
        "dark" => Some((true, false)),
        "high-contrast" => Some((false, true)),
        _ => None,
    }
}

fn preview_window_width(value: Option<&str>) -> f32 {
    bounded_dimension(value, 1_180.0, 720.0, 1_920.0)
}

fn preview_window_height(value: Option<&str>) -> f32 {
    bounded_dimension(value, 760.0, 480.0, 1_200.0)
}

fn bounded_dimension(value: Option<&str>, fallback: f32, minimum: f32, maximum: f32) -> f32 {
    value
        .and_then(|value| value.parse::<f32>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(fallback)
        .clamp(minimum, maximum)
}

fn grid_column_count(viewport_width: f32) -> usize {
    let available = (viewport_width - SIDEBAR_WIDTH - CONTENT_PADDING).max(GRID_ITEM_WIDTH);
    (((available + GRID_GAP) / (GRID_ITEM_WIDTH + GRID_GAP)).floor() as usize).max(1)
}

fn grid_row_count(item_count: usize, columns: usize) -> usize {
    item_count.div_ceil(columns.max(1))
}

fn grid_item_range(row: usize, item_count: usize, columns: usize) -> std::ops::Range<usize> {
    let columns = columns.max(1);
    let start = row.saturating_mul(columns).min(item_count);
    start..start.saturating_add(columns).min(item_count)
}

async fn next_watch_event(
    mut watcher: Box<dyn DirectoryWatch>,
    cancellation: CancellationToken,
) -> Result<(Box<dyn DirectoryWatch>, WatchEvent), StoreError> {
    let event = watcher.next_event(cancellation).await?;
    Ok((watcher, event))
}

fn restore_application_session(
    store: &SessionStore,
    fallback: StorePath,
    exists: impl Fn(&StorePath) -> bool + Copy,
) -> Option<ApplicationSession> {
    for (label, document) in [("primary", store.load()), ("backup", store.load_backup())] {
        match document {
            Ok(Some(document)) => {
                match ApplicationSession::restore_compatible_json(
                    &document,
                    exists,
                    fallback.clone(),
                ) {
                    Ok(session) => return Some(session),
                    Err(error) => {
                        eprintln!(
                            "Musheen could not restore its {label} browsing session: {error}"
                        );
                    }
                }
            }
            Ok(None) => {}
            Err(error) => {
                eprintln!("Musheen could not read its {label} browsing session: {error}");
            }
        }
    }
    None
}

#[derive(Debug)]
struct SessionCoordinator {
    store: SessionStore,
    windows: Vec<(u64, WindowSession)>,
    unknown_fields: BTreeMap<String, serde_json::Value>,
    next_window_id: u64,
    revision: u64,
}

impl SessionCoordinator {
    fn new(store: SessionStore, application: ApplicationSession) -> Self {
        let unknown_fields = application.unknown_fields().clone();
        let windows = application
            .windows()
            .iter()
            .cloned()
            .enumerate()
            .map(|(index, window)| (index as u64 + 1, window))
            .collect::<Vec<_>>();
        Self {
            store,
            unknown_fields,
            next_window_id: windows.len() as u64 + 1,
            windows,
            revision: 0,
        }
    }

    fn entries(&self) -> Vec<(u64, WindowSession)> {
        self.windows.clone()
    }

    fn can_append(&self) -> bool {
        self.windows.len() < MAX_WINDOWS
    }

    fn append(&mut self, window: WindowSession) -> Result<u64, NavigationError> {
        if !self.can_append() {
            return Err(NavigationError::LimitReached("windows"));
        }
        let id = self.next_window_id;
        self.next_window_id = self.next_window_id.saturating_add(1);
        self.windows.push((id, window));
        Ok(id)
    }

    fn remove_window(&mut self, id: u64) -> Result<Option<(u64, Vec<u8>)>, NavigationError> {
        if self.windows.len() <= 1 || !self.windows.iter().any(|(window_id, _)| *window_id == id) {
            return Ok(None);
        }
        let remaining = self
            .windows
            .iter()
            .filter(|(window_id, _)| *window_id != id)
            .cloned()
            .collect::<Vec<_>>();
        let document =
            ApplicationSession::new(remaining.iter().map(|(_, window)| window.clone()).collect())?
                .with_unknown_fields(self.unknown_fields.clone())
                .to_json()?;
        self.windows = remaining;
        self.revision = self.revision.wrapping_add(1);
        Ok(Some((self.revision, document)))
    }

    fn prepare_save(
        &mut self,
        window_id: u64,
        mut window: WindowSession,
    ) -> Result<(u64, Vec<u8>), NavigationError> {
        let Some((_, saved)) = self.windows.iter_mut().find(|(id, _)| *id == window_id) else {
            return Err(NavigationError::InvalidDocument(
                "window is not registered in the application session".into(),
            ));
        };
        window.preserve_unknown_fields_from(saved);
        *saved = window;
        let document = ApplicationSession::new(
            self.windows
                .iter()
                .map(|(_, window)| window.clone())
                .collect(),
        )?
        .with_unknown_fields(self.unknown_fields.clone())
        .to_json()?;
        self.revision = self.revision.wrapping_add(1);
        Ok((self.revision, document))
    }
}

#[derive(Clone, Debug)]
struct SessionBinding {
    coordinator: Arc<Mutex<SessionCoordinator>>,
    window_id: u64,
    operation_hub: OperationHub,
    volume_runtime: Option<VolumeRuntime>,
    catalog: CatalogBinding,
    providers: ProviderRuntime,
}

#[derive(Debug)]
struct PreparedSessionSave {
    binding: SessionBinding,
    revision: u64,
    document: Vec<u8>,
}

impl PreparedSessionSave {
    fn save_if_current(self) -> Result<bool, musheen_desktop::SessionStoreError> {
        let coordinator = self
            .binding
            .coordinator
            .lock()
            .expect("session coordinator lock is not poisoned");
        if coordinator.revision != self.revision {
            return Ok(false);
        }
        coordinator.store.save(&self.document)?;
        Ok(true)
    }
}

impl SessionBinding {
    fn prepare_remove_window(&self) -> Result<Option<PreparedSessionSave>, NavigationError> {
        let removed = self
            .coordinator
            .lock()
            .expect("session coordinator lock is not poisoned")
            .remove_window(self.window_id)?;
        Ok(removed.map(|(revision, document)| PreparedSessionSave {
            binding: self.clone(),
            revision,
            document,
        }))
    }

    fn prepare_save(&self, window: WindowSession) -> Result<PreparedSessionSave, NavigationError> {
        let (revision, document) = self
            .coordinator
            .lock()
            .expect("session coordinator lock is not poisoned")
            .prepare_save(self.window_id, window)?;
        Ok(PreparedSessionSave {
            binding: self.clone(),
            revision,
            document,
        })
    }

    fn can_append_window(&self) -> bool {
        self.coordinator
            .lock()
            .expect("session coordinator lock is not poisoned")
            .can_append()
    }

    fn append_window(&self, window: WindowSession) -> Result<Self, NavigationError> {
        let window_id = self
            .coordinator
            .lock()
            .expect("session coordinator lock is not poisoned")
            .append(window)?;
        Ok(Self {
            coordinator: Arc::clone(&self.coordinator),
            window_id,
            operation_hub: self.operation_hub.clone(),
            volume_runtime: self.volume_runtime.clone(),
            catalog: self.catalog.clone(),
            providers: self.providers.clone(),
        })
    }
}

