#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct NotificationMarker {
    job: JobId,
    generation: EventGeneration,
}

struct DesktopNotificationOwner {
    enabled: bool,
    sink: Arc<dyn musheen_desktop::NotificationSink>,
    pending: BTreeSet<NotificationMarker>,
    handled: BTreeSet<NotificationMarker>,
    actions: async_channel::Sender<musheen_desktop::NotificationAction>,
}

impl DesktopNotificationOwner {
    fn new(
        enabled: bool,
        sink: Arc<dyn musheen_desktop::NotificationSink>,
        actions: async_channel::Sender<musheen_desktop::NotificationAction>,
    ) -> Self {
        Self {
            enabled,
            sink,
            pending: BTreeSet::new(),
            handled: BTreeSet::new(),
            actions,
        }
    }

    fn claim(&mut self, marker: NotificationMarker) -> bool {
        self.enabled && !self.handled.contains(&marker) && self.pending.insert(marker)
    }

    fn suppress(&mut self, marker: NotificationMarker) {
        self.pending.remove(&marker);
        self.handled.insert(marker);
    }

    fn finish(
        &mut self,
        marker: NotificationMarker,
    ) -> Option<(
        Arc<dyn musheen_desktop::NotificationSink>,
        async_channel::Sender<musheen_desktop::NotificationAction>,
    )> {
        self.pending.remove(&marker);
        self.handled.insert(marker);
        while self.handled.len() > 4_096 {
            let Some(oldest) = self.handled.first().copied() else {
                break;
            };
            self.handled.remove(&oldest);
        }
        self.enabled
            .then(|| (Arc::clone(&self.sink), self.actions.clone()))
    }
}

impl Global for DesktopNotificationOwner {}

impl OperationReservation for HubVolumeReservation {
    fn operations_using(&self) -> Vec<OperationUse> {
        self.0
            .operations()
            .into_iter()
            .map(|(id, kind)| OperationUse::new(MountOperation::new(id.get()), format!("{kind:?}")))
            .collect()
    }
}

impl OperationUsage for HubVolumeUsage {
    fn operations_using(&self, mounts: &[PathBuf]) -> Vec<OperationUse> {
        self.hub
            .operations_using_mounts(mounts)
            .into_iter()
            .map(|(id, kind)| OperationUse::new(MountOperation::new(id.get()), format!("{kind:?}")))
            .collect()
    }

    fn cancel(&self, operations: &[OperationUse]) -> Result<(), VolumeError> {
        for operation in operations {
            let id = musheen_ops::JobId::new(operation.id().get()).ok_or_else(|| {
                VolumeError::CancellationFailed("the operation ID is invalid".into())
            })?;
            self.hub
                .cancel(id)
                .map_err(|error| VolumeError::CancellationFailed(error.to_string().into()))?;
        }
        Ok(())
    }

    fn reserve<'a>(
        &'a self,
        mounts: &[PathBuf],
    ) -> Result<Box<dyn OperationReservation + 'a>, VolumeError> {
        self.hub
            .reserve_mounts(mounts)
            .map(|reservation| Box::new(HubVolumeReservation(reservation)) as Box<_>)
            .map_err(|error| VolumeError::CancellationFailed(error.to_string().into()))
    }
}

