    #[test]
    fn rubber_band_geometry_selects_only_intersected_rows_and_grid_cells() {
        let bounds = Bounds::new(point(px(100.), px(50.)), size(px(800.), px(600.)));
        let list_selection = Bounds::from_corners(
            point(px(110.), px(50. + 16. + 36.)),
            point(px(400.), px(50. + 16. + 36. * 3. - 1.)),
        );
        assert_eq!(
            rubber_band_indices(
                list_selection,
                RubberBandSurface {
                    bounds,
                    layout: Layout::List,
                    item_count: 20,
                    columns: 1,
                    top_inset: 16.0,
                    first_item_index: 0,
                    first_item_offset: 0.0,
                    list_row_height: 36.0,
                },
            ),
            vec![1, 2]
        );

        let grid_selection = Bounds::from_corners(
            point(px(100. + 16. + 128. + 8.), px(50. + 16.)),
            point(px(100. + 16. + 128. * 2. + 8. - 1.), px(50. + 16. + 108.)),
        );
        assert_eq!(
            rubber_band_indices(
                grid_selection,
                RubberBandSurface {
                    bounds,
                    layout: Layout::Grid,
                    item_count: 12,
                    columns: 4,
                    top_inset: 16.0,
                    first_item_index: 0,
                    first_item_offset: 0.0,
                    list_row_height: 36.0,
                },
            ),
            vec![1]
        );
    }

