    struct NoopNotificationSink;

    impl musheen_desktop::NotificationSink for NoopNotificationSink {
        fn send(
            &self,
            _event: &musheen_desktop::NotificationEvent,
            _action_label: &str,
            _actions: async_channel::Sender<musheen_desktop::NotificationAction>,
        ) -> Result<(), Box<str>> {
            Ok(())
        }
    }

    #[test]
    fn terminal_notification_markers_are_global_and_generation_deduplicated() {
        let (actions, _) = async_channel::bounded(1);
        let mut owner =
            DesktopNotificationOwner::new(true, Arc::new(NoopNotificationSink), actions.clone());
        let marker = NotificationMarker {
            job: JobId::new(7).unwrap(),
            generation: EventGeneration::new(4),
        };

        assert!(owner.claim(marker));
        assert!(!owner.claim(marker));
        assert!(owner.finish(marker).is_some());
        assert!(!owner.claim(marker));
        assert!(owner.claim(NotificationMarker {
            generation: EventGeneration::new(5),
            ..marker
        }));
        assert!(
            !DesktopNotificationOwner::new(false, Arc::new(NoopNotificationSink), actions,).claim(
                NotificationMarker {
                    generation: EventGeneration::new(6),
                    ..marker
                }
            )
        );
    }

    #[test]
    fn terminal_notification_actions_reference_registered_commands() {
        let registry = musheen_core::CommandRegistry::built_in();
        for kind in [
            OperationKind::Copy,
            OperationKind::Move,
            OperationKind::Trash,
            OperationKind::PermanentDelete,
            OperationKind::CreateFile,
            OperationKind::CreateDirectory,
            OperationKind::Rename,
            OperationKind::SymbolicLink,
            OperationKind::HardLink,
            OperationKind::SetPermissions,
            OperationKind::SetOwnership,
            OperationKind::SetExtendedAttribute,
            OperationKind::Compress,
            OperationKind::Extract,
            OperationKind::Restore,
            OperationKind::Hash,
            OperationKind::Preview,
        ] {
            let command = operation_command_id(kind);
            assert!(
                registry.get(command.as_str()).is_some(),
                "{kind:?} maps to an unknown notification command"
            );
        }
    }

    #[test]
    fn every_typed_volume_error_and_capacity_suffix_is_localized() {
        let errors = [
            VolumeError::MountTable("the mount table is unavailable".into()),
            VolumeError::Capacity {
                path: PathBuf::from("/media/test"),
                reason: "detail".into(),
            },
            VolumeError::ServiceUnavailable("UDisks2 is unavailable".into()),
            VolumeError::Timeout("operation deadline exceeded".into()),
            VolumeError::Disconnected("the volume worker stopped".into()),
            VolumeError::AuthorizationRequired("an unlock secret is required".into()),
            VolumeError::Busy("the volume is busy".into()),
            VolumeError::Unsupported("UDisks2 did not advertise this action".into()),
            VolumeError::DeadlineExceeded,
            VolumeError::WorkerStopped,
            VolumeError::UnlockSecretRequired,
            VolumeError::ActionUnavailable,
            VolumeError::MountNotExposed,
            VolumeError::StaleObject,
            VolumeError::Disappeared(VolumeId::new("gone").unwrap()),
            VolumeError::InUse(vec![OperationUse::new(MountOperation::new(1), "copy")]),
            VolumeError::CancellationFailed("could not cancel volume users".into()),
            VolumeError::Protocol("invalid desktop-service response".into()),
        ];
        let forbidden = [
            "mount table",
            "UDisks2",
            "deadline exceeded",
            "worker stopped",
            "unlock secret",
            "volume is busy",
            "advertise this action",
            "cancel volume users",
            "desktop-service response",
        ];
        for locale in [Locale::EnUs, Locale::EnXa, Locale::Ar] {
            let catalog = Catalog::load(locale).unwrap();
            assert!(!catalog.message("volume-capacity-free").unwrap().is_empty());
            for error in &errors {
                let rendered = localized_volume_error(&catalog, error);
                assert!(!rendered.is_empty(), "{locale:?}: {error:?}");
                if locale != Locale::EnUs {
                    assert_ne!(
                        rendered.as_ref(),
                        error.to_string(),
                        "{locale:?}: {error:?}"
                    );
                    for phrase in forbidden {
                        assert!(
                            !rendered.contains(phrase),
                            "{locale:?} leaked app-owned English `{phrase}` in `{rendered}`"
                        );
                    }
                }
            }
        }
    }

