    #[derive(Default)]
    struct RecordingApplicationRunner(Mutex<Vec<PreparedLaunch>>);

    impl ProcessRunner for RecordingApplicationRunner {
        fn spawn(&self, launch: &PreparedLaunch) -> std::io::Result<()> {
            self.0.lock().unwrap().push(launch.clone());
            Ok(())
        }
    }

    #[test]
    fn typed_application_failures_preserve_app_count_cause_and_recovery() {
        let catalog = Catalog::load(Locale::EnUs).unwrap();
        let cases = [
            (
                ApplicationActionError::Launch(LaunchError::TerminalUnavailable),
                "configured terminal",
            ),
            (
                ApplicationActionError::Launch(LaunchError::UnrepresentableTargets(Vec::new())),
                "path or URI boundary",
            ),
            (
                ApplicationActionError::Launch(LaunchError::TryExecUnavailable(
                    "missing-viewer".into(),
                )),
                "required executable",
            ),
            (
                ApplicationActionError::Persistence(MimeAppsError::TemporaryFileUnavailable),
                "could not be saved",
            ),
            (
                ApplicationActionError::Launch(LaunchError::Spawn(std::io::Error::other(
                    "spawn refused",
                ))),
                "process could not be started",
            ),
        ];
        for (error, expected) in cases {
            let message = application_action_error_message(&catalog, "Image Viewer", 3, &error);
            assert!(message.contains("Image Viewer — 3 items"));
            assert!(message.contains(expected), "{message}");
            assert!(message.contains("retry or choose another application"));
        }
        let arabic = application_action_error_message(
            &Catalog::load(Locale::Ar).unwrap(),
            "عارض الصور",
            3,
            &ApplicationActionError::Launch(LaunchError::TerminalUnavailable),
        );
        assert!(arabic.contains("عارض الصور — 3 عناصر"));
        assert!(arabic.contains("أعد المحاولة أو اختر تطبيقًا آخر"));
        assert!(!arabic.contains("terminal"));
        let pseudo = application_action_error_message(
            &Catalog::load(Locale::EnXa).unwrap(),
            "Viewer",
            1,
            &ApplicationActionError::Launch(LaunchError::Spawn(std::io::Error::other(
                "failed at /private/untranslated/path",
            ))),
        );
        assert!(!pseudo.contains("/private/untranslated/path"));
        assert!(!pseudo.contains("failed at"));
    }

    #[gpui_kit::test]
    async fn failed_set_default_retains_its_actionable_error_when_invalidation_cancels_pending_commands(
        cx: &mut TestAppContext,
    ) {
        cx.update(gpui_kit::init);
        let temporary = tempfile::tempdir().unwrap();
        let path = temporary.path().join("item.txt");
        filesystem::write(&path, b"test").unwrap();
        let item = LocalStore::new()
            .resolve_item(&StorePath::from_unix_path(path.as_os_str()))
            .unwrap()
            .unwrap();
        let target = CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap();
        let mut app = None;
        let handle = cx.open_window(size(px(960.), px(760.)), |window, cx| {
            let view = cx.new(|cx| {
                MusheenApp::new_with_session_store(temporary.path().to_path_buf(), None, cx)
            });
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.unwrap();

        app.update(cx, |state, _| {
            let application = musheen_core::DesktopApplicationId::new("viewer.desktop").unwrap();
            state.pending_application_commands = vec![
                PendingApplicationCommand {
                    action: CommandAction::Open,
                    parameters: CommandParameters::targets(vec![target.clone()]),
                    origin: None,
                },
                PendingApplicationCommand {
                    action: CommandAction::OpenWith,
                    parameters: CommandParameters::open_with(
                        vec![target.clone()],
                        application,
                        CoreOpenWithIntent::OpenOnce,
                    ),
                    origin: None,
                },
                PendingApplicationCommand {
                    action: CommandAction::ChooseApplication,
                    parameters: CommandParameters::targets(vec![target]),
                    origin: None,
                },
            ];
            let expected = state.application_action_error(
                "Image Viewer",
                1,
                &ApplicationActionError::Persistence(MimeAppsError::TemporaryFileUnavailable),
            );

            let canceled = state.complete_application_action(
                "Image Viewer",
                1,
                Err(ApplicationActionError::Persistence(
                    MimeAppsError::TemporaryFileUnavailable,
                )),
                true,
            );

            assert_eq!(state.operation_error.as_deref(), Some(expected.as_ref()));
            assert!(state.pending_application_commands.is_empty());
            assert_eq!(
                canceled,
                PendingApplicationCancellation {
                    open: 1,
                    open_with: 1,
                    choose: 1,
                    set_default: 0,
                }
            );
            assert_eq!(
                state.application_notice,
                Some("application-pending-canceled")
            );
            assert_eq!(
                state
                    .catalog
                    .message(state.application_notice.unwrap())
                    .unwrap(),
                "Pending application commands were canceled because application associations changed."
            );
        });
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            let notice = window.find("application-notice");
            assert!(notice.visible());
            assert_eq!(
                notice.label(),
                Some(
                    "Pending application commands were canceled because application associations changed."
                )
            );
        })
        .unwrap();
    }

    #[test]
    fn desktop_application_snapshot_cache_is_bounded_and_identity_keyed() {
        let provider = ProviderId::new("local").unwrap();
        let mut service = DesktopApplicationService::default();
        let selections = (0..=MAX_DESKTOP_APPLICATION_SNAPSHOTS)
            .map(|index| {
                let bytes = format!("item-{index}").into_bytes();
                vec![
                    CommandTargetRef::new(
                        ItemId::new(provider.clone(), bytes.clone()).unwrap(),
                        StorePath::from_unix_bytes(
                            [b"/tmp/".as_slice(), bytes.as_slice()].concat(),
                        ),
                    )
                    .unwrap(),
                ]
            })
            .collect::<Vec<_>>();
        for selection in &selections {
            assert!(service.begin_refresh(selection));
        }
        assert_eq!(service.entries.len(), MAX_DESKTOP_APPLICATION_SNAPSHOTS);
        assert!(service.queue.len() <= MAX_DESKTOP_APPLICATION_SNAPSHOTS);
        assert!(service.state(&selections[0]).is_none());
        assert!(matches!(
            service.state(selections.last().unwrap()),
            Some(DesktopApplicationSnapshotState::Loading)
        ));
    }

    #[test]
    fn desktop_application_workers_bound_active_and_queued_churn_and_expire_catalogs() {
        let temporary = tempfile::tempdir().unwrap();
        let paths = DesktopPaths::new(
            temporary.path().join("config"),
            temporary.path().join("data"),
        );
        let loader = SystemDesktopApplicationSnapshotLoader;
        let catalog = loader
            .load_catalog(paths, Arc::new(FreedesktopIconProvider))
            .unwrap();
        let mut service = DesktopApplicationService {
            catalog: DesktopCatalogState::Ready {
                loaded_at: Instant::now(),
                snapshot: Arc::new(catalog),
            },
            ..DesktopApplicationService::default()
        };
        let provider = ProviderId::new("local").unwrap();
        for index in 0..100 {
            let bytes = format!("queued-{index}").into_bytes();
            let target = CommandTargetRef::new(
                ItemId::new(provider.clone(), bytes.clone()).unwrap(),
                StorePath::from_unix_bytes([b"/tmp/".as_slice(), &bytes].concat()),
            )
            .unwrap();
            service.begin_refresh(&[target]);
        }
        assert_eq!(service.entries.len(), MAX_DESKTOP_APPLICATION_SNAPSHOTS);
        assert!(service.queue.len() <= MAX_DESKTOP_APPLICATION_SNAPSHOTS);
        assert!(service.next_selection().is_some());
        assert!(service.next_selection().is_some());
        assert!(service.next_selection().is_none());
        assert_eq!(service.active_jobs, MAX_DESKTOP_APPLICATION_JOBS);
        assert!(service.queue.len() <= MAX_DESKTOP_APPLICATION_SNAPSHOTS - 2);

        if let DesktopCatalogState::Ready { loaded_at, .. } = &mut service.catalog {
            *loaded_at = Instant::now() - DESKTOP_APPLICATION_TTL;
        }
        service.expire_catalog();
        assert_eq!(
            service.active_jobs, MAX_DESKTOP_APPLICATION_JOBS,
            "invalidation keeps the two in-flight jobs counted until completion"
        );
        assert!(matches!(service.catalog, DesktopCatalogState::Empty));
        assert!(service.entries.is_empty());
        assert!(service.queue.is_empty());
    }

    #[test]
    fn hidden_default_is_launchable_but_absent_from_chooser_snapshot() {
        let temporary = tempfile::tempdir().unwrap();
        let config = temporary.path().join("config");
        let data = temporary.path().join("data");
        let application = data.join("applications/hidden.desktop");
        filesystem::create_dir_all(application.parent().unwrap()).unwrap();
        filesystem::create_dir_all(&config).unwrap();
        filesystem::write(
            &application,
            "[Desktop Entry]\nType=Application\nName=Hidden\nExec=/usr/bin/true %F\nMimeType=text/plain;\nNoDisplay=true\n",
        )
        .unwrap();
        filesystem::write(
            config.join("mimeapps.list"),
            "[Default Applications]\ntext/plain=hidden.desktop;\n",
        )
        .unwrap();
        let item_path = temporary.path().join("item.txt");
        filesystem::write(&item_path, b"text").unwrap();
        let item = LocalStore::new()
            .resolve_item(&StorePath::from_unix_path(item_path.as_os_str()))
            .unwrap()
            .unwrap();
        let target = CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap();
        let paths =
            DesktopPaths::new(config, data).with_executable_dirs([PathBuf::from("/usr/bin")]);
        let loader = SystemDesktopApplicationSnapshotLoader;
        let catalog = loader
            .load_catalog(paths.clone(), Arc::new(FreedesktopIconProvider))
            .unwrap();
        let providers = ProviderRuntime::for_current_user();
        let snapshot = loader
            .load_selection(&catalog, providers.clone(), vec![target.clone()])
            .unwrap();
        assert!(
            snapshot
                .choices
                .iter()
                .all(|choice| choice.desktop_id() != "hidden.desktop")
        );
        let default = snapshot.default_application.unwrap();
        assert_eq!(default.desktop_id(), "hidden.desktop");
        let (_, launch_targets) = resolve_application_targets(&providers, &[target]).unwrap();
        let prepared = DesktopEntryLauncher::new(paths.executable_dirs().to_vec())
            .prepare(&default, &launch_targets, None)
            .unwrap();
        let runner = RecordingApplicationRunner::default();
        DesktopEntryLauncher::new(paths.executable_dirs().to_vec())
            .launch(&prepared, &runner)
            .unwrap();
        assert_eq!(runner.0.lock().unwrap().len(), 1);
    }

    struct BlockingSnapshotLoader {
        scans: std::sync::atomic::AtomicUsize,
    }

    impl DesktopApplicationSnapshotLoader for BlockingSnapshotLoader {
        fn load_catalog(
            &self,
            _paths: DesktopPaths,
            _icons: Arc<dyn ApplicationIconProvider>,
        ) -> Result<DesktopApplicationCatalogSnapshot, DesktopApplicationLoadError> {
            self.scans.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            std::thread::sleep(Duration::from_millis(300));
            Err(DesktopApplicationLoadError::Associations)
        }

        fn load_selection(
            &self,
            _catalog: &DesktopApplicationCatalogSnapshot,
            _providers: ProviderRuntime,
            _selection: Vec<CommandTargetRef>,
        ) -> Result<DesktopApplicationSnapshot, DesktopApplicationLoadError> {
            unreachable!("a failed catalog scan never schedules selection work")
        }
    }

    #[gpui_kit::test]
    async fn context_menu_returns_while_the_desktop_application_scan_is_blocked(
        cx: &mut TestAppContext,
    ) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let temporary = tempfile::tempdir().unwrap();
        filesystem::write(temporary.path().join("item.txt"), b"test").unwrap();
        let loader = Arc::new(BlockingSnapshotLoader {
            scans: std::sync::atomic::AtomicUsize::new(0),
        });
        let mut app = None;
        let handle = cx.open_window(size(px(960.), px(760.)), |window, cx| {
            let loader = Arc::clone(&loader);
            let view = cx.new(|cx| {
                let mut state = MusheenApp::new_with_navigation(
                    WindowSession::new(StorePath::from_unix_path(
                        temporary.path().as_os_str().to_owned(),
                    )),
                    None,
                    None,
                    ResourceLimits::default(),
                    false,
                    cx,
                );
                state.desktop_paths = Some(DesktopPaths::new(
                    temporary.path().join("config"),
                    temporary.path().join("data"),
                ));
                state.desktop_applications.loader = loader;
                state
            });
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.unwrap();
        let browser: AnyWindowHandle = handle.into();
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                let tab = state.navigation.focused_tab().id();
                let item = state.focused_directory().view().items()[0].id().clone();
                let menu = state.item_context_menu(tab, item, cx);
                let open_with = MusheenApp::menu_entry_by_id(&menu, "file.open_with").unwrap();
                assert!(open_with.submenu().unwrap().entries().iter().any(|entry| {
                    entry.label() == state.catalog.message("application-open-loading").unwrap()
                        && !entry.state().is_enabled()
                        && entry.accessible_disabled_reason()
                            == Some(state.catalog.message("application-open-loading").unwrap())
                        && entry.command_id().is_none()
                }));
                assert!(
                    state
                        .desktop_applications
                        .state(
                            state
                                .active_command_request(CommandAction::Open)
                                .selection()
                        )
                        .is_some_and(|state| matches!(
                            state,
                            DesktopApplicationSnapshotState::Loading
                        ))
                );
            });
        })
        .unwrap();
        cx.wait_for(browser, Duration::from_secs(2), |_, _| {
            loader.scans.load(std::sync::atomic::Ordering::SeqCst) == 1
        })
        .await;
        assert_eq!(loader.scans.load(std::sync::atomic::Ordering::SeqCst), 1);
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            let state = app.read(cx);
            let selection = state
                .active_command_request(CommandAction::Open)
                .selection()
                .to_vec();
            matches!(
                state.desktop_applications.state(&selection),
                Some(DesktopApplicationSnapshotState::Error(_))
            )
        })
        .await;
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, _| {
                let tab = state.navigation.focused_tab().id();
                let selection = state
                    .active_command_request(CommandAction::Open)
                    .selection()
                    .to_vec();
                let menu = state.compose_context_menu(tab, MenuTarget::Item, selection);
                let open_with = MusheenApp::menu_entry_by_id(&menu, "file.open_with").unwrap();
                assert!(open_with.submenu().unwrap().entries().iter().any(|entry| {
                    entry.label()
                        == state
                            .catalog
                            .message("application-open-association-unavailable")
                            .unwrap()
                        && !entry.state().is_enabled()
                }));
            });
        })
        .unwrap();
    }

    #[gpui_kit::test]
    async fn open_nested_set_default_popup_rebuilds_in_place_from_loading_to_ready(
        cx: &mut TestAppContext,
    ) {
        cx.update(gpui_kit::init);
        let temporary = tempfile::tempdir().unwrap();
        filesystem::write(temporary.path().join("item.txt"), b"test").unwrap();
        let mut app = None;
        let handle = cx.open_window(size(px(960.), px(760.)), |window, cx| {
            let view = cx.new(|cx| {
                MusheenApp::new_with_session_store(temporary.path().to_path_buf(), None, cx)
            });
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.unwrap();
        let browser: AnyWindowHandle = handle.into();
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;

        let mut selection = Vec::new();
        let mut nested_menu = None;
        let mut projection = Vec::new();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                let tab = state.navigation.focused_tab().id();
                let item = state.focused_directory().view().items()[0].clone();
                state.select_item(tab, item.id().clone(), cx);
                state.focus_directory_item(tab, Some(item.id().clone()), cx);
                selection
                    .push(CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap());
                let trash_menu =
                    state.compose_context_menu(tab, MenuTarget::TrashItem, selection.clone());
                assert_eq!(
                    trash_menu
                        .entries()
                        .iter()
                        .find_map(|entry| entry.invocation.as_ref())
                        .map(|invocation| invocation.menu_target),
                    Some(MenuTarget::TrashItem),
                    "popup recomposition retains the originating target surface"
                );
                state.desktop_applications.entries.insert(
                    DesktopApplicationService::key(&selection),
                    (1, DesktopApplicationSnapshotState::Loading),
                );
                let menu = state.compose_context_menu(tab, MenuTarget::Item, selection.clone());
                let open_index = menu
                    .entries()
                    .iter()
                    .position(|entry| entry.command_id() == Some("file.open_with"))
                    .unwrap();
                let open_segment =
                    crate::menus::MenuProjectionSegment::for_entry(menu.entries(), open_index);
                let open_menu = menu.entries()[open_index].submenu().unwrap();
                let default_index = open_menu
                    .entries()
                    .iter()
                    .position(|entry| entry.command_id() == Some("file.set_default_application"))
                    .unwrap();
                projection.push(open_segment);
                projection.push(crate::menus::MenuProjectionSegment::for_entry(
                    open_menu.entries(),
                    default_index,
                ));
                nested_menu = open_menu.entries()[default_index].submenu().cloned();
            });
        })
        .unwrap();

        let nested_menu = nested_menu.unwrap();
        assert_eq!(nested_menu.entries().len(), 1);
        let mut popup = None;
        let popup_window = cx.open_window(size(px(420.), px(360.)), |window, cx| {
            let menu = nested_menu.clone();
            let built = PopupMenu::build(window, cx, move |popup, window, cx| {
                crate::menus::ContextMenuRenderer::populate(
                    popup,
                    menu,
                    "set-default-live",
                    window,
                    cx,
                    |_, _, _| {},
                )
            });
            built.update(cx, |popup, cx| popup.focus_handle(cx).focus(window, cx));
            popup = Some(built.clone());
            Root::new(built, window, cx)
        });
        let popup = popup.unwrap();
        let popup_id = popup.entity_id();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, _| {
                state
                    .live_application_popups
                    .push(custom_actions::LiveActionPopup {
                        popup: popup.downgrade(),
                        window: popup_window.into(),
                        menu: nested_menu,
                        path: "set-default-live".into(),
                        projection,
                        target: MenuTarget::Item,
                    });
            });
        })
        .unwrap();

        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                state.desktop_applications.entries.insert(
                    DesktopApplicationService::key(&selection),
                    (
                        2,
                        DesktopApplicationSnapshotState::Ready(Arc::new(
                            DesktopApplicationSnapshot {
                                selection: ResolvedApplicationSelection {
                                    mime_type: "text/plain".into(),
                                },
                                choices: vec![
                                    crate::dialogs::ApplicationChoice::new(
                                        "org.example.Alpha.desktop",
                                        "Alpha Viewer",
                                        true,
                                    ),
                                    crate::dialogs::ApplicationChoice::new(
                                        "org.example.Beta.desktop",
                                        "Beta Viewer",
                                        true,
                                    ),
                                ],
                                applications: HashMap::new(),
                                default_application: None,
                            },
                        )),
                    ),
                );
                state.refresh_application_popups(cx);
            });
        })
        .unwrap();
        assert_eq!(
            popup.entity_id(),
            popup_id,
            "the open popup entity is reused"
        );
        cx.update_window(popup_window.into(), |_, window, cx| {
            window.activate_accessibility_for_test();
            window.render_frame(cx);
            let tree: serde_json::Value =
                serde_json::from_str(&window.debug_a11y_tree_json().unwrap()).unwrap();
            let labels = tree["nodes"]
                .as_object()
                .unwrap()
                .values()
                .filter_map(|node| node["aria"]["label"].as_str())
                .collect::<Vec<_>>();
            assert!(labels.contains(&"Alpha Viewer"));
            assert!(labels.contains(&"Beta Viewer"));
        })
        .unwrap();
    }

