        let (app, browser) = open_selected_directory_with_store(
            temporary.path(),
            Layout::List,
            Some(session_store.clone()),
            cx,
        )
        .await;
        let item = LocalStore::new()
            .resolve_item(&StorePath::from_unix_path(destination.as_os_str()))
            .unwrap()
            .unwrap();
