    // UXF-012: a sidebar location that links to a file is not a directory,
    // so the directory commands are not offered while Open stays available
    // for the file.
    #[gpui_kit::test]
    async fn sidebar_open_in_new_tab_is_disabled_for_a_link_to_a_file(cx: &mut TestAppContext) {
        let (app, _browser, _temporary, location) =
            open_app_with_external_location(ExternalLocation::LinkToFile, cx).await;

        // The place is resolved at the store off the UI thread: ask, then
        // compose again.
        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            state.sidebar_entry_context_menu(
                tab,
                MenuTarget::SidebarLocation,
                location.clone(),
                None,
            );
            assert!(state.run_pending_menu_probes(cx));
        });
        cx.run_until_parked();
        app.update(cx, |state, _| {
            let tab = state.navigation.focused_tab().id();
            let menu =
                state.sidebar_entry_context_menu(tab, MenuTarget::SidebarLocation, location, None);
            for command in ["directory.open_new_tab", "directory.open_new_window"] {
                let offered = MusheenApp::menu_entry_by_id(&menu, command)
                    .is_some_and(|entry| entry.state().is_enabled());
                assert!(!offered, "{command} is not offered on a link to a file");
            }
            let open = MusheenApp::menu_entry_by_id(&menu, "file.open").expect("Open is offered");
            assert!(
                open.state().is_enabled(),
                "a linked file opens with its application"
            );
        });
    }

    // UXF-012: a sidebar location whose link target is gone offers nothing
    // to open; no open command is enabled.
    #[gpui_kit::test]
    async fn sidebar_open_commands_are_disabled_for_a_dangling_link(cx: &mut TestAppContext) {
        let (app, _browser, _temporary, location) =
            open_app_with_external_location(ExternalLocation::DanglingLink, cx).await;

        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            state.sidebar_entry_context_menu(
                tab,
                MenuTarget::SidebarLocation,
                location.clone(),
                None,
            );
            assert!(state.run_pending_menu_probes(cx));
        });
        cx.run_until_parked();
        app.update(cx, |state, _| {
            let tab = state.navigation.focused_tab().id();
            let menu =
                state.sidebar_entry_context_menu(tab, MenuTarget::SidebarLocation, location, None);
            for command in [
                "file.open",
                "directory.open_new_tab",
                "directory.open_new_window",
            ] {
                let enabled = MusheenApp::menu_entry_by_id(&menu, command)
                    .is_some_and(|entry| entry.state().is_enabled());
                assert!(!enabled, "{command} must not be offered on a dangling link");
            }
        });
    }

    // UXF-012: with one pane open, "Open in other pane" splits the pane and
    // shows the location in the new one. Keyboard and D-Bus callers reach
    // this arm with a target outside the focused directory.
    #[gpui_kit::test]
    async fn sidebar_open_in_other_pane_splits_the_pane_and_shows_the_location(
        cx: &mut TestAppContext,
    ) {
        let (app, _browser, _temporary, location) = open_app_with_external_directory(cx).await;

        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            let target = local_command_target(location.as_unix_path().unwrap());
            state.dispatch_typed_context_command(
                CommandAction::OpenInOtherPane,
                CommandParameters::targets(vec![target]),
                Some(tab),
                None,
                false,
                cx,
            );
        });
        cx.run_until_parked();
        app.update(cx, |state, _| {
            assert_eq!(state.navigation.panes().len(), 2, "a second pane opens");
            let focused = state.navigation.focused_tab();
            assert_eq!(focused.location(), &location);
            assert!(
                state.directories.contains_key(&focused.id()),
                "the new pane's tab owns a directory model"
            );
            assert!(
                state.operation_error.is_none(),
                "no error is shown: {:?}",
                state.operation_error
            );
        });
    }

    // UXF-012: a target whose identity changed since the menu was built is
    // refused as changed; nothing opens on the replacement.
    #[gpui_kit::test]
    async fn sidebar_open_in_new_tab_refuses_a_target_whose_identity_changed(
        cx: &mut TestAppContext,
    ) {
        let (app, _browser, _temporary, location) = open_app_with_external_directory(cx).await;

        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            let other = state
                .store
                .resolve_item(state.navigation.focused_tab().location())
                .unwrap()
                .expect("the current directory exists")
                .id()
                .clone();
            let menu = state.sidebar_entry_context_menu(
                tab,
                MenuTarget::SidebarLocation,
                location.clone(),
                Some(other),
            );
            let entry = MusheenApp::menu_entry_by_id(&menu, "directory.open_new_tab")
                .expect("the sidebar menu offers the command")
                .clone();
            state.dispatch_context_entry(entry, cx);
        });
        cx.run_until_parked();
        app.update(cx, |state, _| {
            let expected = state.catalog.message("context.target-changed").unwrap();
            assert_eq!(
                state.navigation.focused_pane().tabs().len(),
                1,
                "no tab opens on a changed target"
            );
            assert_eq!(state.operation_error.as_deref(), Some(expected));
        });
    }

    #[gpui_kit::test]
    async fn keyboard_context_menu_uses_the_focused_pane_target(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../musheen-test-support/fixtures/shell-gallery");
        let mut app = None;
        let handle = cx.open_window(size(px(1_180.), px(760.)), |window, cx| {
            let view = cx.new(|cx| MusheenApp::new_with_session_store(fixture, None, cx));
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.expect("test window constructs the application view");
        cx.wait_for(handle.into(), Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            window.press("down", cx);
            assert_eq!(
                app.read(cx).focused_directory().view().selected_ids().len(),
                1
            );
            assert!(
                app.read(cx)
                    .focused_directory()
                    .view()
                    .focused_item_id()
                    .is_some()
            );
            window.press("shift-f10", cx);
            window.render_frame(cx);
            assert!(window.find("keyboard-context-menu").visible());
            assert!(window.find("popup-menu").visible());
        })
        .expect("test window remains open");
        // The rows arrive once the store answered off the UI thread.
        cx.run_until_parked();
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            let row_id = format!(
                "context-menu-row-keyboard-{:?}-0",
                app.read(cx).navigation.focused_tab().id()
            );
            assert!(window.find(row_id).visible());
            window.press("escape", cx);
            window.render_frame(cx);
            assert!(window.try_find("keyboard-context-menu").is_none());
            assert_eq!(window.find("directory-content").focused(), Some(true));
        })
        .expect("test window remains open");
    }

    #[gpui_kit::test]
    async fn closing_a_context_modal_restores_content_focus_without_dispatching(
        cx: &mut TestAppContext,
    ) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../musheen-test-support/fixtures/shell-gallery");
        let mut app = None;
        let handle = cx.open_window(size(px(1_180.), px(760.)), |window, cx| {
            let view = cx.new(|cx| MusheenApp::new_with_session_store(fixture, None, cx));
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.expect("test window constructs the application view");
        cx.wait_for(handle.into(), Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;
        let mut dialog_handle: Option<AnyWindowHandle> = None;
        let prior_focus = cx
            .update_window(handle.into(), |_, window, cx| {
                window.render_frame(cx);
                window.press("ctrl-l", cx);
                window.focused(cx).expect("location editor is focused")
            })
            .unwrap();
        cx.update(|cx| {
            let strings = ContextDialogStrings::from_catalog(
                &Catalog::load(Locale::EnUs).expect("English catalog loads"),
            );
            let dialog = cx
                .open_window(WindowOptions::default(), |window, cx| {
                    let view =
                        cx.new(|cx| ContextDestinationDialog::new(Vec::new(), strings, window, cx));
                    cx.new(|cx| Root::new(view, window, cx))
                })
                .expect("context modal opens");
            dialog_handle = Some(dialog.into());
            app.update(cx, |state, cx| {
                state.track_context_dialog_window(dialog.window_id(), None, cx);
                assert_eq!(state.context_dialog_windows.len(), 1);
            });
        });
        let dialog_handle = dialog_handle.expect("dialog handle is retained");
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            window.click("omnibar-search", cx);
            assert_eq!(app.read(cx).omnibar.mode(), OmnibarMode::Path);
            assert!(prior_focus.is_focused(window));
            window.right_click("directory-content", cx);
            window.render_frame(cx);
            assert!(window.try_find("popup-menu").is_none());
            assert!(app.read(cx).pending_context_menu.is_none());
        })
        .unwrap();
        cx.update(|cx| {
            app.update(cx, |state, cx| {
                let before = state.focused_directory().view().preferences().layout;
                state.dispatch_command("view.list", cx);
                assert_eq!(
                    state.focused_directory().view().preferences().layout,
                    before
                );
                let location = state.navigation.focused_tab().location().clone();
                state.navigate(StorePath::from_unix_path("/tmp"), true, cx);
                assert_eq!(state.navigation.focused_tab().location(), &location);
            });
        });
        cx.update(|cx| {
            dialog_handle
                .update(cx, |_, window, _| window.remove_window())
                .expect("context modal is open");
        });
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            assert!(app.read(cx).context_dialog_windows.is_empty());
            assert!(prior_focus.is_focused(window));
        })
        .expect("main window remains open");
    }

    #[gpui_kit::test]
    async fn status_bar_opens_shared_operation_history(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../musheen-test-support/fixtures/shell-gallery");
        let recovery_directory = tempfile::tempdir().expect("recovery directory is available");
        let recovery_destination = StorePath::from_unix_path(
            recovery_directory
                .path()
                .join("restored.txt")
                .into_os_string(),
        );
        let recovery_id = musheen_ops::JobId::new(43).expect("non-zero job ID");
        let recovery_staging = musheen_ops::StagingPath::for_destination(
            &recovery_destination,
            recovery_id,
            musheen_ops::EventGeneration::new(0),
        )
        .expect("staging path derives")
        .path()
        .clone();
        filesystem::write(
            recovery_staging.as_unix_path().expect("staging is local"),
            b"partial",
        )
        .expect("staging writes");
        let mut app = None;
        let handle = cx.open_window(size(px(1_180.), px(760.)), |window, cx| {
            let view = cx.new(|cx| MusheenApp::new_with_session_store(fixture, None, cx));
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.expect("test window constructs the application view");
        cx.wait_for(handle.into(), Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;
        cx.update(|cx| {
            app.update(cx, |state, cx| {
                let id = musheen_ops::JobId::new(41).expect("non-zero job ID");
                state
                    .operation_hub
                    .status()
                    .lock()
                    .expect("status center lock is available")
                    .register(
                        id,
                        musheen_ops::EventGeneration::new(0),
                        musheen_ops::OperationKind::Copy,
                        StorePath::from_unix_path("/fixture/Welcome.md"),
                        Some(1),
                    )
                    .expect("operation registers");
                let completed = musheen_ops::JobId::new(42).expect("non-zero job ID");
                let status = state.operation_hub.status();
                let mut status = status.lock().expect("status center lock is available");
                status
                    .register(
                        completed,
                        musheen_ops::EventGeneration::new(0),
                        musheen_ops::OperationKind::Move,
                        StorePath::from_unix_path("/fixture/Archive"),
                        Some(1),
                    )
                    .expect("completed operation registers");
                status.mark_running(completed).unwrap();
                status.record_item_success(completed).unwrap();
                status.complete(completed).unwrap();
                status
                    .register(
                        recovery_id,
                        musheen_ops::EventGeneration::new(0),
                        musheen_ops::OperationKind::Copy,
                        recovery_destination.clone(),
                        Some(1),
                    )
                    .unwrap();
                status.mark_running(recovery_id).unwrap();
                status
                    .record_recoverable_failure(
                        recovery_id,
                        recovery_destination.clone(),
                        recovery_staging.clone(),
                        "recovery staging remains",
                    )
                    .unwrap();
                status.mark_recoverable(recovery_id).unwrap();
                cx.notify();
            });
        });

        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            assert_eq!(
                window.find("operation-status-summary").label(),
                Some("Copy: 0 of 1")
            );
            window.click("operation-status-summary", cx);
            window.render_frame(cx);
            assert!(window.find("operation-status-center").visible());
            assert!(window.find("operation-status-41").visible());
            assert!(window.find("operation-status-42").visible());
            assert!(window.find("operation-recovery-discard-43").visible());
            assert!(window.try_find("operation-recovery-resume-43").is_none());
            assert!(window.find("operation-view-43").visible());
            window.click("operation-recovery-discard-43", cx);
            window.render_frame(cx);
            assert!(
                !recovery_staging
                    .as_unix_path()
                    .expect("staging is local")
                    .exists()
            );
            assert!(window.try_find("operation-recovery-discard-43").is_none());
            window.click("operation-dismiss-42", cx);
            window.render_frame(cx);
            assert!(window.try_find("operation-status-42").is_none());
        })
        .expect("test window remains open");
    }

    #[gpui_kit::test]
    async fn completed_rename_offers_guarded_undo_from_operation_history(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let temporary = tempfile::tempdir().unwrap();
        let source_path = temporary.path().join("before.txt");
        filesystem::write(&source_path, b"contents").unwrap();
        let source = StorePath::from_unix_path(source_path.as_os_str());
        let mut store = LocalStore::new();
        let identity = musheen_ops::MutationProvider::identity(&mut store, &source)
            .unwrap()
            .unwrap();
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../musheen-test-support/fixtures/shell-gallery");
        let mut app = None;
        let handle = cx.open_window(size(px(1_180.), px(760.)), |window, cx| {
            let view = cx.new(|cx| MusheenApp::new_with_session_store(fixture, None, cx));
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.unwrap();
        let job = cx.update(|cx| {
            app.update(cx, |state, cx| {
                let job = state
                    .operation_hub
                    .submit_rename(RenameRequest::new(
                        source,
                        "after.txt".into(),
                        identity.into_vec(),
                    ))
                    .unwrap();
                state.pump_operation_queue(cx);
                job
            })
        });
        cx.wait_for(handle.into(), Duration::from_secs(3), |_, cx| {
            app.read(cx)
                .operation_hub
                .status()
                .lock()
                .unwrap()
                .entry(job)
                .is_some_and(|entry| entry.status() == OperationStatus::Completed)
        })
        .await;
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            window.click("operation-status-summary", cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            window.click(format!("operation-undo-{}", job.get()), cx);
        })
        .unwrap();
        cx.wait_for(handle.into(), Duration::from_secs(3), |_, cx| {
            source_path.exists()
                && app
                    .read(cx)
                    .operation_hub
                    .status()
                    .lock()
                    .unwrap()
                    .visible_entries()
                    .iter()
                    .any(|entry| {
                        entry.id() != job
                            && entry.kind() == OperationKind::Rename
                            && entry.status() == OperationStatus::Completed
                    })
        })
        .await;
        assert_eq!(filesystem::read(source_path).unwrap(), b"contents");
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            assert!(
                window
                    .try_find(format!("operation-undo-{}", job.get()))
                    .is_none()
            );
        })
        .unwrap();
    }

