    #[gpui_kit::test]
    async fn local_browser_navigates_and_runs_core_file_verbs_through_the_hub(
        cx: &mut TestAppContext,
    ) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let temporary = tempfile::tempdir().unwrap();
        let child = temporary.path().join("child");
        filesystem::create_dir(&child).unwrap();
        let mut app = None;
        let handle = cx.open_window(size(px(960.), px(760.)), |window, cx| {
            let view = cx.new(|cx| {
                MusheenApp::new_with_session_store(temporary.path().to_path_buf(), None, cx)
            });
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let browser: AnyWindowHandle = handle.into();
        let app = app.unwrap();
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;

        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            let item = state
                .focused_directory()
                .items()
                .iter()
                .find(|item| item.path().as_unix_path() == Some(child.as_path()))
                .unwrap();
            state.focus_directory_item(tab, Some(item.id().clone()), cx);
            state.activate_focused_directory_item(cx);
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx)
                .navigation
                .focused_tab()
                .location()
                .as_unix_path()
                == Some(child.as_path())
        })
        .await;

        app.update(cx, |state, cx| {
            state.navigate(
                StorePath::from_unix_path(temporary.path().as_os_str()),
                true,
                cx,
            );
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            let state = app.read(cx);
            state.navigation.focused_tab().location().as_unix_path() == Some(temporary.path())
                && state.focused_directory().state() == &DirectoryState::Ready
        })
        .await;
        app.update(cx, |state, cx| {
            state.submit_name_operation(
                NameOperation::Create {
                    parent: StorePath::from_unix_path(temporary.path().as_os_str()),
                    kind: musheen_ops::CreateKind::Directory,
                },
                "created".to_owned(),
                cx,
            );
        });
        let created = temporary.path().join("created");
        cx.wait_for(browser, Duration::from_secs(2), |_, _| created.is_dir())
            .await;

        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx)
                .focused_directory()
                .items()
                .iter()
                .any(|item| item.path().as_unix_path() == Some(created.as_path()))
        })
        .await;
        app.update(cx, |state, cx| {
            let item = state
                .focused_directory()
                .items()
                .iter()
                .find(|item| item.path().as_unix_path() == Some(created.as_path()))
                .unwrap();
            let target = CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap();
            state.submit_name_operation(NameOperation::rename(target), "renamed".to_owned(), cx);
        });
        let renamed = temporary.path().join("renamed");
        cx.wait_for(browser, Duration::from_secs(2), |_, _| renamed.is_dir())
            .await;
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx)
                .focused_directory()
                .items()
                .iter()
                .any(|item| item.path().as_unix_path() == Some(renamed.as_path()))
        })
        .await;
        app.update(cx, |state, cx| {
            let item = state
                .focused_directory()
                .items()
                .iter()
                .find(|item| item.path().as_unix_path() == Some(renamed.as_path()))
                .unwrap();
            state.submit_delete_targets(
                vec![CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap()],
                true,
                cx,
            );
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, _| !renamed.exists())
            .await;

        let copy_source = temporary.path().join("copy-me.txt");
        filesystem::write(&copy_source, b"copy").unwrap();
        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            state.start_load_for_tab(
                tab,
                StorePath::from_unix_path(temporary.path().as_os_str()),
                cx,
            );
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx)
                .focused_directory()
                .items()
                .iter()
                .any(|item| item.path().as_unix_path() == Some(copy_source.as_path()))
        })
        .await;
        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            let item = state
                .focused_directory()
                .items()
                .iter()
                .find(|item| item.path().as_unix_path() == Some(copy_source.as_path()))
                .unwrap();
            let target = CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap();
            state.select_item(tab, item.id().clone(), cx);
            state.dispatch_typed_context_command(
                CommandAction::Copy,
                CommandParameters::targets(vec![target]),
                Some(tab),
                None,
                false,
                cx,
            );
            paste_tests::assert_active_paste_targets_current_folder(state, temporary.path());
            state.paste_file_clipboard(StorePath::from_unix_path(child.as_os_str()), cx);
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, _| {
            child.join("copy-me.txt").is_file()
        })
        .await;
        assert!(copy_source.is_file());

        let cut_source = temporary.path().join("cut-me.txt");
        filesystem::write(&cut_source, b"cut").unwrap();
        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            state.start_load_for_tab(
                tab,
                StorePath::from_unix_path(temporary.path().as_os_str()),
                cx,
            );
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx)
                .focused_directory()
                .items()
                .iter()
                .any(|item| item.path().as_unix_path() == Some(cut_source.as_path()))
        })
        .await;
        app.update(cx, |state, cx| {
            let tab = state.navigation.focused_tab().id();
            let item = state
                .focused_directory()
                .items()
                .iter()
                .find(|item| item.path().as_unix_path() == Some(cut_source.as_path()))
                .unwrap();
            let target = CommandTargetRef::new(item.id().clone(), item.path().clone()).unwrap();
            state.dispatch_typed_context_command(
                CommandAction::Cut,
                CommandParameters::targets(vec![target]),
                Some(tab),
                None,
                false,
                cx,
            );
            state.paste_file_clipboard(StorePath::from_unix_path(child.as_os_str()), cx);
        });
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            !cut_source.exists()
                && child.join("cut-me.txt").is_file()
                && app.read(cx).file_clipboard.is_none()
        })
        .await;
    }

    /// A gate the test closes around a store's metadata calls. A call that
    /// arrives while the gate is closed waits; after two seconds it panics,
    /// so a UI thread that waits on the store fails the test instead of
    /// hanging it.
    #[derive(Default)]
    struct StoreGate {
        closed: Mutex<bool>,
        opened: std::sync::Condvar,
        passes: std::sync::atomic::AtomicUsize,
    }

    impl StoreGate {
        fn close(&self) {
            *self.closed.lock().unwrap() = true;
        }

        fn open(&self) {
            *self.closed.lock().unwrap() = false;
            self.opened.notify_all();
        }

        fn pass(&self) {
            self.passes
                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let mut closed = self.closed.lock().unwrap();
            let deadline = Instant::now() + Duration::from_secs(2);
            while *closed {
                let now = Instant::now();
                assert!(
                    now < deadline,
                    "a store metadata call waited two seconds at the gate: the UI thread is waiting on the store"
                );
                closed = self.opened.wait_timeout(closed, deadline - now).unwrap().0;
            }
        }
    }

    /// The local store with its metadata calls behind a [`StoreGate`].
    struct GatedStore {
        inner: Arc<dyn Store>,
        gate: Arc<StoreGate>,
    }

    impl Store for GatedStore {
        fn provider_id(&self) -> &ProviderId {
            self.inner.provider_id()
        }

        fn capabilities(&self, location: &StorePath) -> CapabilityMatrix {
            self.gate.pass();
            self.inner.capabilities(location)
        }

        fn resolve_item(&self, path: &StorePath) -> Result<Option<StoreItem>, StoreError> {
            self.gate.pass();
            self.inner.resolve_item(path)
        }

        fn resolve_link_target(&self, path: &StorePath) -> Result<Option<StoreItem>, StoreError> {
            self.gate.pass();
            self.inner.resolve_link_target(path)
        }

        fn location_writable(&self, path: &StorePath) -> Result<CapabilityState, StoreError> {
            self.gate.pass();
            self.inner.location_writable(path)
        }

        fn executable_state(&self, path: &StorePath) -> Result<CapabilityState, StoreError> {
            self.gate.pass();
            self.inner.executable_state(path)
        }

        fn search_capabilities(&self, location: &StorePath) -> SearchCapabilities {
            self.inner.search_capabilities(location)
        }

        fn search<'a>(
            &'a self,
            scope: &'a StorePath,
            query: musheen_core::SearchQuery,
            cancellation: CancellationToken,
        ) -> musheen_core::BoxFuture<'a, Result<Box<dyn musheen_core::SearchStream>, StoreError>>
        {
            self.inner.search(scope, query, cancellation)
        }

        fn read_directory<'a>(
            &'a self,
            location: &'a StorePath,
            request: PageRequest,
            cancellation: CancellationToken,
        ) -> musheen_core::BoxFuture<'a, Result<Page<StoreItem>, StoreError>> {
            self.inner.read_directory(location, request, cancellation)
        }

        fn watch_directory<'a>(
            &'a self,
            location: &'a StorePath,
            cancellation: CancellationToken,
        ) -> musheen_core::BoxFuture<'a, Result<Box<dyn musheen_core::DirectoryWatch>, StoreError>>
        {
            self.inner.watch_directory(location, cancellation)
        }

        fn validate_mutation(&self, request: &MutationRequest) -> Result<(), StoreError> {
            self.inner.validate_mutation(request)
        }

        fn mutate<'a>(
            &'a self,
            request: MutationRequest,
            cancellation: CancellationToken,
        ) -> musheen_core::BoxFuture<'a, Result<(), StoreError>> {
            self.inner.mutate(request, cancellation)
        }
    }

    #[gpui_kit::test]
    async fn ui_thread_context_menu_opens_while_the_store_metadata_call_is_blocked(
        cx: &mut TestAppContext,
    ) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let temporary = tempfile::tempdir().unwrap();
        filesystem::write(temporary.path().join("item.txt"), b"test").unwrap();
        let mut app = None;
        let handle = cx.open_window(size(px(960.), px(760.)), |window, cx| {
            let view = cx.new(|cx| {
                MusheenApp::new_with_navigation(
                    WindowSession::new(StorePath::from_unix_path(
                        temporary.path().as_os_str().to_owned(),
                    )),
                    None,
                    None,
                    ResourceLimits::default(),
                    false,
                    cx,
                )
            });
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.unwrap();
        let browser: AnyWindowHandle = handle.into();
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Ready
        })
        .await;

        let gate = Arc::new(StoreGate::default());
        gate.close();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                state.store = Arc::new(GatedStore {
                    inner: Arc::clone(&state.store),
                    gate: Arc::clone(&gate),
                });
                let tab = state.navigation.focused_tab().id();
                let item = state.focused_directory().view().items()[0].id().clone();
                // The store is blocked, and the menu still opens.
                let menu = state.item_context_menu(tab, item, cx);
                assert!(
                    MusheenApp::menu_entry_by_id(&menu, "file.open_with").is_some(),
                    "the menu opens for the file while the store is blocked"
                );
            });
        })
        .unwrap();

        gate.open();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                assert!(
                    state.run_pending_menu_probes(cx),
                    "the menu queued the store questions it could not answer"
                );
            });
        })
        .unwrap();
        cx.wait_for(browser, Duration::from_secs(2), |_, _| {
            gate.passes.load(std::sync::atomic::Ordering::SeqCst) >= 1
        })
        .await;
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, _| {
                let tab = state.navigation.focused_tab().id();
                let selection = state
                    .active_command_request(CommandAction::Open)
                    .selection()
                    .to_vec();
                let menu = state.compose_context_menu(tab, MenuTarget::Item, selection);
                assert!(MusheenApp::menu_entry_by_id(&menu, "file.open_with").is_some());
            });
        })
        .unwrap();
    }

    /// A watcher whose next event never comes.
    struct StalledWatch;

    impl musheen_core::DirectoryWatch for StalledWatch {
        fn semantics(&self) -> musheen_core::WatchSemantics {
            musheen_core::WatchSemantics::Live
        }

        fn next_event<'a>(
            &'a mut self,
            _cancellation: CancellationToken,
        ) -> musheen_core::BoxFuture<'a, Result<WatchEvent, StoreError>> {
            Box::pin(async { Err(StoreError::Cancelled) })
        }
    }

    #[gpui_kit::test]
    async fn ui_thread_watch_event_applies_while_the_catalog_lock_is_held(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            install_navigation_key_bindings(cx);
        });
        let temporary = tempfile::tempdir().unwrap();
        let folder = temporary.path().join("watched");
        filesystem::create_dir(&folder).unwrap();
        let catalog_path = temporary.path().join("private/catalog.json");
        let catalog_store = CatalogStore::at(&catalog_path);
        catalog_store.save(&CatalogDocument::default()).unwrap();
        let limits = ResourceLimits::default();
        let providers = ProviderRuntime::for_current_user();
        let navigation =
            WindowSession::new(StorePath::from_unix_path(folder.as_os_str().to_owned()));
        let coordinator = Arc::new(Mutex::new(SessionCoordinator::new(
            SessionStore::at(temporary.path().join("session.json")),
            ApplicationSession::new(vec![navigation.clone()]).unwrap(),
        )));
        let window_id = coordinator.lock().unwrap().entries()[0].0;
        let binding = SessionBinding {
            coordinator,
            window_id,
            operation_hub: OperationHub::new_with_provider_runtime(&limits, &providers),
            volume_runtime: None,
            catalog: CatalogBinding::persistent_with_xattr_opt_in(
                catalog_store,
                CatalogDocument::default(),
                true,
            ),
            providers,
        };
        let mut app = None;
        let handle = cx.open_window(size(px(960.), px(760.)), |window, cx| {
            let view = cx.new(|cx| {
                MusheenApp::new_with_navigation(navigation, Some(binding), None, limits, false, cx)
            });
            app = Some(view.clone());
            Root::new(view, window, cx)
        });
        let app = app.unwrap();
        let browser: AnyWindowHandle = handle.into();
        cx.wait_for(browser, Duration::from_secs(2), |_, cx| {
            app.read(cx).focused_directory().state() == &DirectoryState::Empty
        })
        .await;

        // Another process holds the catalog lock for the next two seconds.
        let mut lock_path = catalog_path.as_os_str().to_owned();
        lock_path.push(".lock");
        let lock_file = standard_library::fs::OpenOptions::new()
            .create(true)
            .truncate(false)
            .read(true)
            .write(true)
            .open(&lock_path)
            .unwrap();
        rustix::fs::flock(&lock_file, rustix::fs::FlockOperation::LockExclusive).unwrap();
        let (release, released) = std::sync::mpsc::channel::<()>();
        let holder = std::thread::spawn(move || {
            let _ = released.recv_timeout(Duration::from_secs(2));
            drop(lock_file);
        });

        let created = folder.join("new.txt");
        filesystem::write(&created, b"new").unwrap();
        let item = LocalStore::new()
            .resolve_item(&StorePath::from_unix_path(created.as_os_str().to_owned()))
            .unwrap()
            .unwrap();
        let started = Instant::now();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                let tab = state.navigation.focused_tab().id();
                let load = state.focused_directory().current_load().unwrap();
                state.handle_watch_event(
                    tab,
                    load,
                    Box::new(StalledWatch),
                    WatchEvent::Created(item.clone()),
                    cx,
                );
                assert!(
                    state.focused_directory().view().item(item.id()).is_some(),
                    "the directory model shows the created item"
                );
            });
        })
        .unwrap();
        let elapsed = started.elapsed();
        let _ = release.send(());
        holder.join().unwrap();
        assert!(
            elapsed < Duration::from_secs(1),
            "applying the watch event took {elapsed:?}: the UI thread waited on the catalog lock"
        );
        cx.run_until_parked();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, _| {
                assert_eq!(state.operation_error, None);
            });
        })
        .unwrap();
    }

    #[gpui_kit::test]
    async fn theme_fallback_installs_the_preferred_variant_last(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            let preferences = native_theme::AccessibilityPreferences::default();
            install_fallback_theme(true, &preferences, cx);
            assert!(
                cx.theme().mode.is_dark(),
                "a window that prefers dark gets the dark fallback"
            );
            install_fallback_theme(false, &preferences, cx);
            assert!(
                !cx.theme().mode.is_dark(),
                "a window that prefers light gets the light fallback"
            );
        });
    }

    // UIV-014: the fallback follows the window appearance, dark or light,
    // through the same mapping install_native_theme uses.
    #[test]
    fn theme_fallback_preference_follows_the_window_appearance() {
        assert!(prefers_dark_appearance(gpui_kit::WindowAppearance::Dark));
        assert!(prefers_dark_appearance(
            gpui_kit::WindowAppearance::VibrantDark
        ));
        assert!(!prefers_dark_appearance(gpui_kit::WindowAppearance::Light));
        assert!(!prefers_dark_appearance(
            gpui_kit::WindowAppearance::VibrantLight
        ));
    }

    /// The items a test adds to a folder after it is open, as the watcher
    /// would report them.
    fn late_items(folder: &Path, count: usize) -> Vec<StoreItem> {
        (0..count)
            .map(|number| {
                let path = folder.join(format!("late-{number}.txt"));
                filesystem::write(&path, b"late").unwrap();
                LocalStore::new()
                    .resolve_item(&StorePath::from_unix_path(path.as_os_str().to_owned()))
                    .unwrap()
                    .unwrap()
            })
            .collect()
    }

    #[gpui_kit::test]
    async fn indexed_folder_merge_batches_the_changes_that_arrive_while_one_runs(
        cx: &mut TestAppContext,
    ) {
        let temporary = write_large_folder(&[]);
        let (app, browser, tab_id, _index_root) =
            open_large_folder(temporary.path(), Layout::List, cx).await;
        let items = late_items(temporary.path(), 3);
        let before = cx.read(|cx| app.read(cx).focused_directory().indexed_count());

        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                state.index_merges_started = 0;
                let load = state.focused_directory().current_load().unwrap();
                for item in &items {
                    state.handle_watch_event(
                        tab_id,
                        load.clone(),
                        Box::new(StalledWatch),
                        WatchEvent::Created(item.clone()),
                        cx,
                    );
                }
                assert!(
                    state.index_merges_running.contains(&tab_id),
                    "the first change starts a merge"
                );
                assert_eq!(
                    state.pending_index_events.get(&tab_id).map_or(0, Vec::len),
                    2,
                    "the changes that arrive while it runs wait for the next merge"
                );
            });
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, _| {
                assert_eq!(
                    state.index_merges_started, 2,
                    "one merge for the first change and one for the two that waited"
                );
                assert_eq!(state.focused_directory().indexed_count(), before + 3);
                assert!(!state.index_merges_running.contains(&tab_id));
                assert!(
                    state
                        .pending_index_events
                        .get(&tab_id)
                        .is_none_or(Vec::is_empty)
                );
                assert_eq!(state.operation_error, None);
            });
        })
        .unwrap();
    }

    #[gpui_kit::test]
    async fn indexed_folder_merge_failure_is_reported_by_the_window(cx: &mut TestAppContext) {
        let temporary = write_large_folder(&[]);
        let (app, browser, tab_id, _index_root) =
            open_large_folder(temporary.path(), Layout::List, cx).await;
        let item = late_items(temporary.path(), 1).remove(0);
        let before = cx.read(|cx| app.read(cx).focused_directory().indexed_count());

        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, cx| {
                // The index directory stops accepting new files, so the merge
                // cannot write the new order.
                state
                    .focused_directory()
                    .set_index_directory_mode(0o500)
                    .unwrap();
                let load = state.focused_directory().current_load().unwrap();
                state.handle_watch_event(
                    tab_id,
                    load,
                    Box::new(StalledWatch),
                    WatchEvent::Created(item),
                    cx,
                );
            });
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(browser, |_, _, cx| {
            app.update(cx, |state, _| {
                state
                    .focused_directory()
                    .set_index_directory_mode(0o700)
                    .unwrap();
                assert_eq!(
                    state.focused_directory().state(),
                    &DirectoryState::Ready,
                    "the items already shown stay on screen"
                );
                assert_eq!(state.focused_directory().indexed_count(), before);
                assert!(
                    state
                        .operation_error
                        .as_deref()
                        .is_some_and(|error| error.contains("Directory index failed")),
                    "the failed merge is reported to the window: {:?}",
                    state.operation_error
                );
            });
        })
        .unwrap();
    }

    // UXF-012 through the caches: a sidebar place is resolved again for each
    // menu, so a link whose target went away after the first menu offers
    // nothing on the next one.
    #[gpui_kit::test]
    async fn sidebar_place_that_becomes_a_dangling_link_offers_nothing_on_the_next_menu(
        cx: &mut TestAppContext,
    ) {
        let (app, _browser, temporary, location) =
            open_app_with_external_location(ExternalLocation::LinkToDirectory, cx).await;
        let compose = |state: &mut MusheenApp| {
            let tab = state.navigation.focused_tab().id();
            state.sidebar_entry_context_menu(
                tab,
                MenuTarget::SidebarLocation,
                location.clone(),
                None,
            )
        };

        app.update(cx, |state, cx| {
            state.begin_sidebar_menu();
            compose(state);
            assert!(state.run_pending_menu_probes(cx));
        });
        cx.run_until_parked();
        app.update(cx, |state, _| {
            let menu = compose(state);
            assert!(
                MusheenApp::menu_entry_by_id(&menu, "directory.open_new_tab")
                    .is_some_and(|entry| entry.state().is_enabled()),
                "a live link to a directory offers the directory commands"
            );
        });

        filesystem::remove_dir(temporary.path().join("real-external")).unwrap();
        app.update(cx, |state, cx| {
            state.begin_sidebar_menu();
            compose(state);
            assert!(
                state.run_pending_menu_probes(cx),
                "the next menu asks the store about the place again"
            );
        });
        cx.run_until_parked();
        app.update(cx, |state, _| {
            let menu = compose(state);
            for command in [
                "file.open",
                "directory.open_new_tab",
                "directory.open_new_window",
            ] {
                let enabled = MusheenApp::menu_entry_by_id(&menu, command)
                    .is_some_and(|entry| entry.state().is_enabled());
                assert!(!enabled, "{command} must not be offered on a dangling link");
            }
        });
    }
